// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Mendel genetiği ve kalıtım problemleri (zor).
const ozBiology9Zor = <(String, String, List<String>, String)>[
  ('\'Gen\' terimini 1909\'da kalıtım birimini adlandırmak için öneren Danimarkalı botanikçi kimdir?', 'Wilhelm Johannsen', ['William Bateson', 'Carl Correns', 'Thomas Hunt Morgan'], 'Johannsen 1909\'da \'gen\' sözcüğünü önermiş; genotip ve fenotip kavramlarını da o ayırt etmiştir.'),
  ('Kalıtım bilimine \'genetik\' adını ilk kez 1905\'te veren İngiliz biyolog kimdir?', 'William Bateson', ['Francis Galton', 'Reginald Punnett', 'Hugo de Vries'], 'Bateson, Mendel\'in görüşlerinin İngiltere\'deki savunucusudur ve \'genetics\' terimini 1905\'te önermiştir.'),
  ('Mendel\'in bezelyede bulduğu düzenlilikleri doğrulamak için çalıştığı şahin otunda (Hieracium) tutarsız sonuçlar almasının sonradan anlaşılan nedeni nedir?', 'Bu bitkinin döllenme olmadan tohum oluşturabilmesi', ['Bu bitkinin hiç çiçek açmaması', 'Bu bitkide genlerin bulunmaması', 'Bu bitkinin yalnızca köksaplarla, vejetatif yolla çoğalabilmesi'], 'Hieracium\'da tohumlar çoğu kez döllenmesiz oluşur; döller ana bitkinin kopyası olduğundan Mendel oranları ortaya çıkmaz.'),
  ('Bağımsız açılan genler için AaBbCc × AaBbCc çaprazlamasında üç karakterden en az birinde çekinik fenotip gösteren döllerin oranı nedir?', '37/64', ['27/64', '1/64', '9/64'], 'Üçünde de baskın fenotip olasılığı (3/4)³ = 27/64\'tür; tümleyeni 1 − 27/64 = 37/64 olur.'),
  ('Bağımsız açılan dört gen için AaBbCcDd × AaBbCcDd çaprazlamasında tam olarak iki karakterde baskın, iki karakterde çekinik fenotipli döllerin oranı nedir?', '27/128', ['9/256', '9/64', '81/256'], 'Hangi ikisinin baskın olacağı 6 farklı biçimde seçilir; 6 × (3/4)² × (1/4)² = 54/256 = 27/128.'),
  ('Otozomal çekinik bir hastalık için taşıyıcı olan bir çiftin iki çocuğundan en az birinin hasta olma olasılığı nedir?', '7/16', ['1/4', '1/2', '9/16'], 'İkisinin de sağlıklı olma olasılığı (3/4)² = 9/16\'dır; en az birinin hasta olma olasılığı 1 − 9/16 = 7/16.'),
  ('Genotipi bilinmeyen baskın fenotipli bir tavşan çekinik bir tavşanla çiftleştiriliyor ve doğan 5 yavrunun tamamı baskın fenotipte oluyor. Tavşan aslında heterozigot olsaydı böyle bir sonucun şansla ortaya çıkma olasılığı ne olurdu?', '1/32', ['1/5', '1/10', '1/16'], 'Heterozigot × çekinik çaprazlamasında her yavrunun baskın olma olasılığı 1/2\'dir; beş yavru için (1/2)⁵ = 1/32.'),
  ('Bir yetiştirici, baskın fenotipli bir boğanın heterozigot olma olasılığını test çaprazlamasıyla dışlamak istiyor. Boğa heterozigot olduğu hâlde bütün yavruların baskın çıkma olasılığının %1\'in altına inmesi için en az kaç yavru gözlenmelidir?', '7', ['5', '4', '10'], '(1/2)⁶ = 1/64 ≈ %1,6 ve (1/2)⁷ = 1/128 ≈ %0,8 olduğundan en az 7 yavru gerekir.'),
  ('Saf döl AAbb ve aaBB bitkileri çaprazlanarak F2 elde ediliyor. F2\'de ebeveynlerin hiçbirinde görülmeyen yeni fenotip birleşimlerinin (A_B_ ve aabb) toplam oranı nedir?', '10/16', ['6/16', '9/16', '4/16'], 'Bu kez ebeveyn fenotipleri A_bb (3/16) ve aaB_ (3/16)\'dir; yeni birleşimler 9/16 + 1/16 = 10/16 olur.'),
  ('AaBb × AaBb çaprazlamasından (genler bağımsız) elde edilen F2\'de çift baskın fenotipli bitkilerin kaçta kaçı her iki karakter bakımından saf döldür?', '1/9', ['1/16', '1/4', '1/3'], 'Çift baskın fenotipliler 9 paydır; bunlardan yalnız AABB (1 pay) iki karakter için de homozigottur: 1/9.'),
  ('Mendel\'in ayrılma ilkesini sınamak isteyen bir öğrenci F2\'deki bütün bireylerin kendi aralarında rastgele çiftleşmesine izin veriyor (seçilim yok). Aa × Aa ile başlayan bu deneyde F3\'te çekinik fenotipin beklenen oranı nedir?', '1/4', ['1/9', '3/8', '1/16'], 'F2\'de A ve a alellerinin oranları hâlâ 1/2\'dir; rastgele çiftleşmede aa olasılığı (1/2)² = 1/4 olarak kalır.'),
  ('Aa × Aa çaprazlamasından elde edilen F2\'deki çekinik bireyler ayıklanıyor ve kalan baskın fenotipliler kendi aralarında rastgele çiftleştiriliyor. Döllerde çekinik fenotip oranı nedir?', '1/9', ['1/4', '1/6', '1/16'], 'Kalanlar 1/3 AA ve 2/3 Aa\'dır; a alelinin oranı 1/3\'tür. Rastgele çiftleşmede aa = (1/3)² = 1/9.'),
  ('Aa × Aa çaprazlamasından elde edilen F2 bitkilerinin her biri ayrı ayrı kendileştiriliyor. F3 kuşağının tamamında çekinik fenotipli bitkilerin oranı nedir?', '3/8', ['1/4', '1/2', '5/8'], 'aa\'lar (1/4) yalnız aa verir; Aa\'lar (1/2) dölleri içinde 1/4 aa verir. Toplam 1/4 + 1/2 × 1/4 = 3/8.'),
  ('Mısır tarımında yıllar boyu kendileştirilmiş iki saf hattın melezlenmesiyle elde edilen tohumların her yıl yeniden satın alınmasının genetik nedeni nedir?', 'F2 döllerinde açılım olması ve melez üstünlüğünün azalması', ['Melez tohumlarının ikinci yıl toprakta hiç çimlenmemesi ve çürümesi', 'Melez bitkilerin çiçek açmaması', 'Melez bitkilerin kısır olması'], 'F1 melezleri heterozigottur; bunların dölleri (F2) açılım gösterir ve F1\'deki tekdüze yüksek verim korunamaz.'),
  ('Eksik baskınlıkta heterozigot bireyin ara fenotip göstermesinin moleküler düzeydeki olası açıklaması hangisidir?', 'Tek işlevli alelin pigmentin ancak yarısını üretebilmesi', ['Çekinik alelin baskın aleli kalıcı olarak bozması', 'İki alelin DNA düzeyinde birleşip yeni ve ara özellikli bir gen oluşturması', 'Heterozigot bireyde iki alelin de hiç ifade edilmemesi'], 'Pek çok eksik baskınlık örneğinde işlevli alel tek kopya olduğunda ürün miktarı yarıya iner ve renk ara tonda kalır.'),
  ('Tay-Sachs hastalığı organizma düzeyinde çekinik kalıtılır; ancak taşıyıcıların hücrelerinde ilgili enzimin etkinliği sağlıklı homozigotlarınkinin yaklaşık yarısıdır. Bu durum baskınlık hakkında neyi gösterir?', 'Baskınlığın, incelenen düzeye göre farklı yorumlanabileceğini', ['Hastalığın aslında eşeye bağlı olduğunu', 'Taşıyıcıların hastalığı her zaman daha hafif ve geç yaşta geçirdiğini', 'Enzim miktarının alellerle ilgisi olmadığını'], 'Organizma düzeyinde yarım enzim yeterli olduğu için taşıyıcı sağlıklıdır (çekinik); enzim düzeyinde ise ara değer görülür (eksik baskınlık).'),
  ('Mendel\'in düz (R) ve buruşuk (r) bezelye tohumlarında makroskobik olarak düz tohum tam baskındır; ancak heterozigot tohumlardaki nişasta tanelerinin boyut ve biçimi iki homozigotun arasında kalır. Bu gözlemden hangi sonuç çıkarılabilir?', 'Aynı alel çifti, mikroskobik düzeyde eksik baskınlık gösterebilir', ['Tohum biçimi aslında iki farklı ve birbirine bağlı genle belirlenir', 'Heterozigot tohumlar kısırdır', 'Nişasta miktarı çevre koşullarıyla belirlenir'], 'Görünürde tam baskın olan bir özellik, hücresel düzeyde ölçüldüğünde ara fenotip gösterebilir; baskınlık türü gözlem düzeyine bağlıdır.'),
  ('A kan grubundan (I^A i) ve MN kan grubundan bir anne ile B kan grubundan (I^B i) ve MN kan grubundan bir babanın çocuğunun hem AB hem de MN kan grubundan olma olasılığı nedir?', '1/8', ['1/4', '1/16', '3/8'], 'AB olma olasılığı 1/4, MN olma olasılığı (MN × MN) 1/2\'dir; bağımsız olduklarından 1/4 × 1/2 = 1/8.'),
  ('ABO sisteminde i alelinin I^A ve I^B alellerine karşı çekinik davranmasının moleküler açıklaması hangisidir?', 'i alelinin işlevli bir şeker ekleyici enzim üretememesi', ['i alelinin I^A ve I^B alellerinin DNA\'sını kesmesi', 'i alelinin yalnız erkeklerde ifade edilmesi', 'i alelinin alyuvar zarında üçüncü bir antijen oluşturması'], 'I^A ve I^B alelleri zar yüzeyine farklı şekiller ekleyen enzimleri kodlar; i alelinin ürünü işlevsiz olduğundan heterozigotta yalnız öteki alelin antijeni görülür.'),
  ('Kistik fibrozis otozomal çekinik kalıtılır. Bir erkeğin ve evleneceği kadının birer kardeşi kistik fibrozis hastasıdır; dört ebeveyn ve çiftin kendisi sağlıklıdır. Bu çiftin ilk çocuğunun hasta olma olasılığı nedir?', '1/9', ['1/4', '1/16', '1/6'], 'Her birinin taşıyıcı olma olasılığı 2/3\'tür; ikisinin de taşıyıcı olup çocuğa çekinik alel aktarması 2/3 × 2/3 × 1/4 = 1/9 eder.'),
  ('Albinizm otozomal çekinik kalıtılır. Sağlıklı bir kadının kardeşi albinodur, anne ve babası sağlıklıdır. Bu kadın, annesi albino olan sağlıklı bir erkekle evleniyor. Çocuklarının albino olma olasılığı nedir?', '1/6', ['1/4', '1/8', '1/9'], 'Kadının taşıyıcı olma olasılığı 2/3, erkeğin ise 1\'dir (annesinden kesin a almış); 2/3 × 1 × 1/4 = 1/6.'),
  ('Çekinik bir hastalık için taşıyıcı olma olasılığı 2/3 olan bir kadın, taşıyıcılık sıklığının 1/50 olduğu bir toplumdan, ailesinde hastalık bulunmayan bir erkekle evleniyor. Çocuklarının hasta olma olasılığı nedir?', '1/300', ['1/200', '1/150', '1/600'], '2/3 × 1/50 × 1/4 = 2/600 = 1/300.'),
  ('Akondroplazi alelini homozigot taşıyan embriyolar doğumdan önce ya da kısa süre sonra ölür. İki heterozigot akondroplazili ebeveynin canlı doğan çocukları arasında akondroplazili olanların beklenen oranı nedir?', '2/3', ['1/2', '3/4', '1/4'], 'Aa × Aa döllerinden AA olanlar yaşamaz; kalan Aa (2 pay) ve aa (1 pay) arasında akondroplazililer 2/3\'tür.'),
  ('X\'e bağlı baskın bir alel erkek embriyolarda ölümcüldür. Bu aleli taşıyan bir kadın sağlıklı bir erkekle evlenirse canlı doğan çocuklarında beklenen kız : erkek oranı nedir?', '2 : 1', ['1 : 1', '1 : 2', '3 : 1'], 'Kızların tamamı (biri hasta, biri sağlıklı) yaşarken oğulların alel taşıyan yarısı ölür; 2 kız payına 1 erkek payı kalır.'),
  ('Beyaz gözlü dişi (XʷXʷ) ile kırmızı gözlü erkek (XᴿY) meyve sineklerinin F1 dölleri kendi aralarında çaprazlanıyor. F2\'de dişiler ve erkekler için göz rengi dağılımı nasıl olur?', 'İki eşeyde de yarı kırmızı, yarı beyaz', ['Dişilerin tamamı kırmızı, erkeklerin yarısı beyaz', 'Dişilerin tamamı beyaz, erkeklerin tamamı kırmızı', 'İki eşeyde de 3 kırmızı : 1 beyaz'], 'F1: XᴿXʷ dişiler ve XʷY erkekler. F2 dişileri XᴿXʷ ya da XʷXʷ, erkekleri XᴿY ya da XʷY olur; her eşeyde 1 : 1.'),
  ('Sağlıklı bir kadının erkek kardeşi hemofili hastasıdır; anne ve babası sağlıklıdır. Bu kadının sağlıklı bir erkekle evliliğinden doğacak ilk oğlunun hemofili olma olasılığı nedir?', '1/4', ['1/2', '1/8', '2/3'], 'Anne taşıyıcı olduğundan kadının taşıyıcı olma olasılığı 1/2\'dir; taşıyıcıysa oğluna aktarma olasılığı 1/2: 1/2 × 1/2 = 1/4.'),
  ('Hemofili taşıyıcısı ve albinizm bakımından heterozigot (Aa) bir kadın, sağlıklı ve Aa genotipli bir erkekle evleniyor. Doğacak çocuğun hem hemofili hem albino bir oğul olma olasılığı nedir?', '1/16', ['1/8', '1/32', '1/4'], 'Hemofili hastası oğul olma olasılığı 1/4 (erkek 1/2 × Xʰ 1/2), albino olma olasılığı 1/4; çarpım 1/16.'),
  ('Bir erkek bal arısının ürettiği spermlerin tamamının genetik olarak birbirinin aynısı olmasının nedeni nedir?', 'Haploit erkeğin spermlerini kromozom sayısını azaltmadan üretmesi', ['Spermlerin üretim sırasında krossing-over geçirip yeni alel birleşimleri kazanması', 'Erkek arıların iki takım kromozom taşıması', 'Spermlerin kraliçe tarafından değiştirilmesi'], 'Haploit erkekte ayrılacak homolog kromozom çifti yoktur; spermler mitoz benzeri bir bölünmeyle oluşur ve aynı genetik içeriği taşır.'),
  ('Meyve sineğinde eşey, X kromozomlarının otozom takımlarına oranıyla belirlenir. Buna göre XXY kromozomlu bir meyve sineği hangi eşeyde gelişir?', 'Dişi', ['Erkek', 'Hem dişi hem erkek özellikler taşıyan birey', 'Ölür, canlı birey oluşmaz'], 'Meyve sineğinde Y kromozomu eşeyi belirlemez; XXY bireyde X : otozom oranı 1 olduğundan dişi gelişir. İnsanda ise XXY erkektir.'),
  ('İnsanda XXY bireyin erkek, meyve sineğinde ise dişi olması iki türdeki eşey belirleme ile ilgili neyi gösterir?', 'İnsanda Y\'nin varlığının, sinekte X : otozom oranının belirleyici olduğunu', ['İki türde de eşeyin yalnız X sayısıyla belirlendiğini', 'Sineklerde eşeyin sıcaklıkla belirlendiğini', 'İnsanda Y kromozomunun eşey belirleme üzerinde hiçbir etkisinin olmadığını'], 'İnsanda SRY taşıyan Y erkekliği başlatır; sinekte Y eşey belirlemez, X : otozom oranı belirleyicidir.'),
  ('Tavuklarda çizgili tüy deseni Z kromozomundaki baskın bir alelle belirlenir. Çizgisiz bir horoz çizgili bir tavukla çiftleştirilirse civcivler için hangisi beklenir?', 'Erkek civcivler çizgili, dişi civcivler çizgisiz olur', ['Bütün civcivler çizgili olur', 'Bütün civcivler çizgisiz olur', 'Dişi civcivler çizgili, erkek civcivler ise çizgisiz olur'], 'Horoz ZᵇZᵇ, tavuk Zᴮ W\'dir. Erkek civcivler anneden Zᴮ alıp çizgili olur; dişiler babadan Zᵇ, anneden W alıp çizgisiz olur.'),
  ('Tavukçulukta, Z\'ye bağlı bir renk özelliği kullanılarak civcivlerin daha yumurtadan çıkar çıkmaz erkek ve dişi olarak ayrılabilmesi hangi ilkeye dayanır?', 'Dişilerin tek Z taşıdığı için alelin eşeylere farklı dağılması', ['Erkek civcivlerin daha büyük yumurtalardan çıkması', 'Dişi civcivlerin her zaman daha koyu renkli olması', 'Renk genlerinin yalnızca W kromozomunda bulunup erkeklere hiç geçmemesi'], 'Kuşlarda dişi ZW olduğundan, uygun çaprazlamada babadan gelen Z\'ye bağlı alel dişilerde doğrudan görünür ve eşeyler renkten ayırt edilir.'),
  ('Bazı koyun ırklarında boynuzluluk (H) erkeklerde baskın, dişilerde çekinik davranır. Hh genotipli bir koç ile Hh genotipli bir koyunun bütün kuzuları içinde boynuzlu olanların beklenen oranı nedir?', '1/2', ['3/4', '1/4', '3/8'], 'Erkek kuzuların 3/4\'ü (HH, Hh), dişi kuzuların 1/4\'ü (HH) boynuzludur; eşeyler eşit sayıda ise ortalama (3/4 + 1/4) / 2 = 1/2 eder.'),
  ('X ve Y kromozomlarının uçlarında bulunan ve mayozda eşleşip krossing-over yapabilen \'psödootozomal bölgelerdeki\' genler nasıl bir kalıtım örüntüsü gösterir?', 'Otozomal genlere benzer bir örüntü', ['Yalnız babadan oğula aktarılan Y\'ye bağlı örüntü', 'Yalnız anneden kalıtılan mitokondriyal örüntü', 'Kesinlikle X\'e bağlı çekinik örüntü'], 'Bu bölgelerde X ve Y homolog gibi davranır; genler iki eşey kromozomunda da bulunduğundan otozomal gibi kalıtılır.'),
  ('SRY geninin, mayoz sırasında hatalı bir krossing-over ile X kromozomuna aktarıldığı XX karyotipli bir bireyde hangi fenotip beklenir?', 'Erkek fenotipi', ['Kadın fenotipi', 'Turner sendromu belirtileri', 'Yalnız X\'e bağlı hastalık belirtileri'], 'Testis gelişimini başlatan SRY geni olduğundan, bu geni taşıyan XX birey erkek yönünde gelişir.'),
  ('Deniz solucanı Bonellia\'da serbest yüzen bir larva, dişi bir bireyin hortumuna konarsa erkeğe, açık suda yerleşirse dişiye dönüşür. Bu örnek eşey belirlemenin hangi türüne aittir?', 'Çevresel eşey belirlemesi', ['Kromozomal XY eşey belirlemesi', 'Kromozomal ZW eşey belirlemesi', 'Haplodiploit eşey belirlemesi'], 'Bonellia\'da eşey, genetik farklılıktan değil larvanın karşılaştığı çevresel koşullardan belirlenir.'),
  ('AaBb genotipli bir dişi aabb ile test çaprazlamasına sokuluyor. Döllerin %42\'si Aabb, %42\'si aaBb, %8\'i AaBb ve %8\'i aabb çıkıyor. Dişinin kromozomlarındaki gen dizilimi için hangisi doğrudur?', 'Trans dizilim: her kromozomda bir baskın, bir çekinik alel vardır', ['Cis dizilim: iki baskın alel aynı kromozomda, iki çekinik alel homoloğundadır', 'A ve B farklı kromozomlardadır', 'Dört gen aynı kromozomda yan yana bulunur'], 'En sık görülen sınıflar ebeveyn kromozomlarını gösterir; Ab ve aB gametleri çoğunlukta olduğundan dizilim trans (Ab/aB)\'dir.'),
  ('Erkek meyve sineklerinde mayoz sırasında krossing-over gerçekleşmez. Bu nedenle AB/ab genotipli bir erkek sinek ab/ab dişiyle çaprazlandığında döllerde ne görülür?', 'Yalnız ebeveyn tipi iki fenotip sınıfı', ['Dört fenotip sınıfı eşit oranda', 'Rekombinant sınıfların ebeveyn tiplerinden fazla olması', 'Yalnız rekombinant tipte döller'], 'Erkek sinekte rekombinasyon olmadığından bağlı genler tam bağlı gibi davranır ve yalnız AB ile ab gametleri oluşur.'),
  ('İki gen arasındaki rekombinasyon sıklığının, genler birbirinden ne kadar uzak olursa olsun %50\'yi geçmemesinin nedeni nedir?', 'Her krossing-overın dört kromatitin yalnız ikisini etkilemesi', ['Uzak genlerin farklı hücrelere gitmesi', 'Krossing-overın yalnız kardeş kromatitler arasında gerçekleşip görünmez kalması', 'Kromozomların en fazla yarısının mayoza girmesi'], 'Tek krossing-over dört üründen ikisini rekombinant yapar; uzak genlerde çok sayıda krossing-over olsa da ortalama rekombinant oranı %50\'de sınırlanır.'),
  ('Rekombinasyon sıklıkları A–B arasında %10, B–C arasında %15 bulunduğu hâlde A–C arasında %25 yerine %22 ölçülüyor (sıralama A–B–C). Bu farkın en olası nedeni nedir?', 'Çift krossing-overların rekombinant olarak görünmemesi', ['B geninin aslında başka bir kromozomda bulunması ve bağımsız açılması', 'Ölçümde mutasyonların rekombinant sayılması', 'C geninin X kromozomunda bulunması'], 'A ile C arasında iki krossing-over olursa uçtaki genler ebeveyn düzenine döner; bu döller rekombinant görünmez ve uzak genlerin uzaklığı düşük ölçülür.'),
  ('Üç bağlı gen için yapılan bir test çaprazlamasında en sık sınıflar ABC ve abc, en seyrek sınıflar ise AbC ve aBc\'dir. Ortadaki gen hangisidir?', 'B', ['A', 'C', 'Sıra belirlenemez'], 'En seyrek sınıflar çift krossing-over ürünleridir; ebeveyn düzenine göre yalnız ortadaki gen yer değiştirir. Burada değişen B\'dir.'),
  ('Üç gen için A–B arası %10, B–C arası %20 rekombinasyon ölçülüyor ve çift krossing-over gösteren döllerin oranı %1 bulunuyor. Rastlantı katsayısı (gözlenen / beklenen çift krossing-over) kaçtır?', '0,5', ['2', '0,02', '0,1'], 'Beklenen çift krossing-over 0,10 × 0,20 = 0,02\'dir; 0,01 / 0,02 = 0,5. Girişim 1 − 0,5 = 0,5 olur.'),
  ('A ve B genleri tam bağlıdır (krossing-over yok). AB/ab genotipli bir bitki kendileştirildiğinde döllerde fenotip oranı ne olur?', '3 A_B_ : 1 aabb', ['9 : 3 : 3 : 1', '1 : 2 : 1', '1 A_B_ : 1 A_bb : 1 aaB_ : 1 aabb'], 'Yalnız AB ve ab gametleri oluşur; döller 1 AB/AB : 2 AB/ab : 1 ab/ab, fenotipte 3 çift baskın : 1 çift çekinik olur.'),
  ('Homolog kromozomlarından birinde A ile b, diğerinde a ile B taşıyan ve bu iki lokus arasında hiç rekombinasyon olmayan bir bitki kendi polenleriyle döllenirse yavruların fenotip dağılımı ne olur?', '1 A_bb : 2 A_B_ : 1 aaB_', ['3 A_B_ : 1 aabb', '9 : 3 : 3 : 1', '1 A_B_ : 1 A_bb : 1 aaB_ : 1 aabb'], 'Yalnız Ab ve aB gametleri oluşur; döller 1 Ab/Ab : 2 Ab/aB : 1 aB/aB olur. Ab/aB iki baskın aleli taşıdığından A_B_ fenotiplidir.'),
  ('A ve B genleri arasında rekombinasyon %20\'dir. AB/ab genotipli iki birey çaprazlanırsa (iki eşeyde de krossing-over olduğu varsayılırsa) aabb fenotipli döllerin oranı nedir?', '%16', ['%6,25', '%4', '%40'], 'Her ebeveynin ab gameti oranı %40\'tır; aabb için iki ab gameti gerekir: 0,4 × 0,4 = 0,16.'),
  ('Tırnak-patella sendromuna yol açan baskın alel, ABO kan grubu lokusuna yakın bağlıdır. Bir ailede bu bağlılık hangi amaçla kullanılabilir?', 'Kan grubuyla hastalık alelli kromozomu kuşaklar boyu izlemek', ['Kan grubunu değiştiren bir tedaviyle hastalığın belirtilerini önlemek', 'Hastalığın eşeye bağlı olduğunu kanıtlamak', 'Kan nakliyle hastalığın geçişini önlemek'], 'Yakın bağlı genler birlikte kalıtılma eğiliminde olduğundan, belirlenmesi kolay bir işaretleyici (kan grubu) aracılığıyla hastalık aleli izlenebilir.'),
  ('Rekombinasyon sıklıklarına dayanan genetik haritalardaki uzaklıklar ile DNA üzerindeki gerçek fiziksel uzaklıklar her zaman orantılı değildir. Bunun nedeni nedir?', 'Krossing-over sıklığının kromozomun farklı bölgelerinde farklı olması', ['Genetik haritaların yalnızca X kromozomu ve otozomların bir kısmı için çizilebilmesi', 'DNA\'nın mayozda kısalması', 'Genlerin kromozomdaki yerlerinin her kuşak değişmesi'], 'Bazı bölgelerde krossing-over çok sık (sıcak noktalar), bazılarında (ör. sentromer çevresi) çok seyrektir; bu yüzden harita birimi sabit bir baz sayısına karşılık gelmez.'),
  ('Çoban çantası bitkisinde üçgen ve oval kapsüllü saf hatlar çaprazlandığında F1 üçgen kapsüllü, F2 ise 15 üçgen : 1 oval çıkıyor. Bu oranın en iyi açıklaması hangisidir?', 'İki genden birinin baskın aleli üçgen kapsül için yeterlidir', ['Üçgen kapsül için iki genin de baskın aleli gereklidir', 'Üçgen kapsül eksik baskın bir genle belirlenir', 'Oval kapsül aleli homozigot olduğunda embriyo için letaldir'], '15 : 1, yinelenen (çift) genlerin göstergesidir; yalnız aabb bireyler oval olur.'),
  ('Beyaz Leghorn ile beyaz Wyandotte tavukları çaprazlandığında F1 beyaz, F2 ise 13 beyaz : 3 renkli çıkıyor. Bu sonuç en iyi nasıl açıklanır?', 'Bir gendeki baskın alel renk genini baskılar', ['Renk için iki genin de çekinik homozigot olması gerekir', 'Beyaz renk tek bir genin eksik baskınlığıyla oluşur', 'Renkli bireyler yalnız erkeklerde görülür'], 'Renk için C_ gerekir; ancak baskın I aleli rengi baskılar. Yalnız iiC_ (3/16) renkli, geri kalanlar (13/16) beyazdır.'),
  ('Yazlık kabakta disk ve uzun meyveli saf hatlar çaprazlanınca F1 disk, F2 ise 9 disk : 6 küre : 1 uzun meyveli çıkıyor. F2\'deki küre biçimli meyveler hangi genotip gruplarından oluşur?', 'A_bb ve aaB_', ['A_B_ ve aabb', 'Yalnız aaB_', 'Yalnız A_bb ve aabb'], 'Her iki genin baskın aleli disk (9), yalnız birinin baskın aleli küre (3 + 3 = 6), hiç baskın alel yoksa uzun (1) biçim oluşur.'),
  ('Farelerde A_C_ aguti (kahverengi-gri), aaC_ siyah, cc ise A lokusundan bağımsız olarak albino fenotip verir. AaCc genotipli bir fare aacc ile çiftleştirilirse yavrularda beklenen oran nedir?', '1 aguti : 1 siyah : 2 albino', ['9 aguti : 3 siyah : 4 albino', '1 aguti : 1 siyah : 1 albino : 1 kahverengi', '3 aguti : 1 albino'], 'Döller AaCc (aguti), aaCc (siyah), Aacc ve aacc (ikisi de albino) olur: 1 : 1 : 2.'),
  ('Bir çiçekte beyaz öncül madde A geninin enzimiyle kırmızı pigmente, kırmızı pigment de B geninin enzimiyle mor pigmente dönüşmektedir. aa bireylerde enzim yoksa, bb bireylerde de ikinci enzim yoksa AaBb × AaBb çaprazlamasında beklenen mor : kırmızı : beyaz oranı nedir?', '9 : 3 : 4', ['9 : 7 : 0', '12 : 3 : 1', '9 : 6 : 1'], 'A_B_ mor (9), A_bb kırmızı (3), aa__ ise B\'den bağımsız beyazdır (3 + 1 = 4).'),
  ('Kokulu bezelyede mor çiçek için C_P_ gerekir; öteki bütün genotipler beyazdır (F2\'de 9 : 7). CcPp genotipli mor bir bitki ccpp ile çaprazlanırsa döllerde mor : beyaz oranı nedir?', '1 : 3', ['1 : 1', '9 : 7', '3 : 1'], 'Test çaprazlamasında döllerin yalnız CcPp olanı (1/4) mor, Ccpp, ccPp ve ccpp (3/4) beyazdır.'),
  ('İki genden herhangi birinin baskın alelinin üçgen kapsül için yeterli olduğu (F2\'de 15 : 1) bir bitkide, iki gen için heterozigot bir bitki çift çekinik oval bir bitkiyle çaprazlanırsa döllerde üçgen : oval oranı nedir?', '3 : 1', ['1 : 1', '15 : 1', '1 : 3'], 'Döllerin yalnız aabb olanı (1/4) oval kapsül taşır; diğer üç genotip en az bir baskın alel içerdiğinden üçgendir.'),
  ('Kabaklarda W_ beyaz, wwY_ sarı, wwyy yeşil meyve verir. WwYy genotipli bir bitki wwyy ile çaprazlanırsa döllerde beyaz : sarı : yeşil oranı nedir?', '2 : 1 : 1', ['12 : 3 : 1', '1 : 1 : 2', '9 : 3 : 4'], 'Döller WwYy ve Wwyy (beyaz, 2 pay), wwYy (sarı, 1 pay) ve wwyy (yeşil, 1 pay) olur.'),
  ('Disk meyveyi A_B_, küre meyveyi tek baskın alelli genotiplerin, uzun meyveyi aabb\'nin verdiği kabaklarda AaBb × aabb çaprazlamasının döllerinde disk : küre : uzun oranı nedir?', '1 : 2 : 1', ['9 : 6 : 1', '1 : 1 : 2', '3 : 0 : 1'], 'Döller AaBb (disk), Aabb ve aaBb (küre) ile aabb (uzun) olur: 1 : 2 : 1.'),
  ('Bir bitki türünde iki saf hattın melezinden elde edilen F2\'de 302 yeşil ve 19 sarı fide sayılıyor. Bu sonuç hangi kalıtım modelini en iyi destekler?', 'Yinelenen iki genin bulunduğu 15 : 1 modelini', ['Tek genli 3 : 1 modelini', 'Tamamlayıcı genlerin 9 : 7 modelini', 'Baskın epistasinin görüldüğü 12 : 3 : 1 modelini'], 'Toplam 321 bitkide 15 : 1 beklentisi yaklaşık 301 : 20\'dir; gözlenen değerler buna çok yakındır.'),
  ('Bir dihibrit F2 oranının 9 : 3 : 3 : 1 yerine 9 : 3 : 4 çıkması, oranın toplamı (16) değişmediği için genler hakkında neyi gösterir?', 'Bağımsız açılan genlerin etkileştiğini', ['Genlerin aynı kromozomda tam bağlı olduğunu', 'Bir genotipin letal olduğunu', 'Genlerin X kromozomunda bulunduğunu'], '16 sınıflı dağılım korunduğu için açılım bağımsızdır; yalnız bazı genotip sınıfları aynı fenotipte birleşmiştir.'),
  ('Labrador köpeklerinde B_ siyah, bb kahverengi pigment belirler; ee genotipi ise pigmentin tüye geçmesini engelleyip sarı renk oluşturur. Sarı bir labradorun yavruları arasında siyah ve kahverengi yavrular çıkması neyi gösterir?', 'Sarı köpeğin B lokusunda farklı aleller taşıyabildiğini', ['Sarı rengin B lokusuyla belirlendiğini', 'E ve B genlerinin aynı lokusta bulunduğunu', 'Sarı köpeğin aslında ee değil EE genotipinde olup pigment taşıdığını'], 'ee köpekte B lokusunun etkisi gizlenir ama aleller döllere aktarılır; eşten E alan yavrularda bu aleller fenotipte görünür.'),
  ('Buğday tanesinin kırmızı renk tonlarını inceleyerek sürekli değişen özelliklerin birden çok genin eklemeli etkisiyle açıklanabileceğini 1909\'da gösteren İsveçli genetikçi kimdir?', 'Herman Nilsson-Ehle', ['Wilhelm Ludvig Johannsen', 'Carl von Linné', 'Gregor Mendel'], 'Nilsson-Ehle, buğdayda tane renginin iki ya da üç gen çiftinin eklemeli etkisiyle belirlendiğini göstererek poligenik kalıtımın temelini atmıştır.'),
  ('Bir bitkide boy, eklemeli etki gösteren iki gen çiftiyle belirleniyor: aabb bitkiler 20 cm\'dir ve her baskın (eklemeli) alel boyu 5 cm artırıyor. AaBb × AaBb çaprazlamasından elde edilen döllerin kaçta kaçı 30 cm boyunda olur?', '3/8', ['1/4', '1/16', '9/16'], '30 cm için iki eklemeli alel gerekir; 4 alelden tam 2\'sinin baskın olma olasılığı 6/16 = 3/8\'dir.'),
  ('Eklemeli genlerle belirlenen bir özellik için iki uç saf hattın melezlenmesinden elde edilen F2\'de, uç ebeveyn fenotiplerinden birine sahip bireylerin oranı 1/256 bulunuyor. Bu özelliği kaç gen çifti belirlemektedir?', '4', ['2', '3', '8'], 'n gen çiftinde bir uç fenotipin oranı (1/4)ⁿ\'dir; (1/4)⁴ = 1/256 olduğundan n = 4\'tür.'),
  ('Eklemeli etkili üç gen çifti için AaBbCc × aabbcc çaprazlamasında tam olarak bir eklemeli (büyük harfli) alel taşıyan döllerin oranı nedir?', '3/8', ['1/8', '1/2', '3/16'], 'aabbcc yalnız eklemesiz alel verir; öteki ebeveynin üç lokusundan tam birinde büyük harfli alel verme olasılığı 3 × (1/2)³ = 3/8\'dir.'),
  ('Farelerde sarı kürk aleli homozigot olduğunda embriyo ölür. Sarı × sarı çiftleşmelerinden doğan yavru sayısının, sarı × normal çiftleşmelerine göre ortalama ne kadar olması beklenir?', 'Yaklaşık dörtte üçü kadar', ['Yaklaşık yarısı kadar', 'Aynı sayıda, çünkü ölüm doğumdan sonra olur', 'Yaklaşık iki katı'], 'Sarı × sarı çiftleşmesinde embriyoların 1/4\'ü (homozigot sarı) ölür; sarı × normalde ölüm olmaz. Bu yüzden yavru sayısı yaklaşık 3/4\'e düşer.'),
  ('AA genotipinin embriyoda letal olduğu bir sistemde AaBb × AaBb çaprazlaması yapılıyor (genler bağımsız, B tam baskın). Yaşayan döllerde Aa B_ : Aa bb : aa B_ : aa bb oranı nedir?', '6 : 2 : 3 : 1', ['9 : 3 : 3 : 1', '2 : 1 : 2 : 1', '6 : 3 : 2 : 1'], 'Yaşayanlarda Aa 2/3, aa 1/3\'tür; B_ 3/4, bb 1/4. Paylar: 2×3 = 6, 2×1 = 2, 1×3 = 3, 1×1 = 1.'),
  ('Belirli bir genotipin farklı çevre koşullarında ortaya koyabileceği fenotiplerin tümüne ne ad verilir?', 'Tepki normu', ['Gen havuzu', 'Karyotip', 'Bağlantı grubu'], 'Tepki normu, bir genotipin çevre değişkenlerine göre gösterebileceği fenotip aralığını tanımlar.'),
  ('Bir popülasyonda boyun kalıtsallık derecesinin yüksek bulunması hangi anlama gelir?', 'Popülasyondaki boy farkının çoğunun genetik farklardan doğduğu', ['Her bireyin boyunun yalnız genlerle belirlendiği', 'Beslenmenin boyu hiç etkilemediği', 'Bir bireyin boyunun büyük kısmını annesinden, kalanını babasından aldığı'], 'Kalıtsallık bireye değil popülasyona ait bir ölçüdür; varyasyonun hangi oranının genetik farklılıklara bağlı olduğunu gösterir.'),
  ('Lymnaea salyangozunda sağa kıvrık kabuk aleli (D), sola kıvrık kabuk aleline (d) baskındır ve kabuk yönü maternal etkiyle belirlenir. Genotipi Dd olan bir anneden doğan dd genotipli bir yavrunun kabuğu hangi yöne kıvrılır?', 'Sağa', ['Sola', 'Yarı yarıya sağa ve sola', 'Kıvrılmaz, düz kalır'], 'Maternal etkide yavrunun fenotipini annenin genotipi belirler; anne D aleli taşıdığından bütün yavruların kabuğu sağa kıvrılır. Bu dd yavrunun kendi yavruları ise sola kıvrık olur.'),
  ('Mitokondriyal bir hastalıkta aynı annenin çocuklarında belirtilerin çok hafiften çok ağıra kadar değişmesinin en olası nedeni hangisidir?', 'Hücrelerdeki normal ve mutant mitokondri oranının farklı olması', ['Hastalık aleliyle ilgili olarak babadan gelen çekirdek genlerinin her çocukta değişmesi', 'Hastalığın Y kromozomuna bağlı olması', 'Çocukların farklı kan gruplarına sahip olması'], 'Bir hücrede yüzlerce mitokondri bulunur; mutant ve normal mtDNA\'nın karışık bulunması (heteroplazmi) ve bunların döllere farklı oranlarda geçmesi belirtilerin şiddetini değiştirir.'),
  ('Ani görme kaybıyla seyreden ve yalnız anneden çocuklara aktarılan Leber kalıtsal optik nöropatisinin kalıtım biçimi hangisidir?', 'Mitokondriyal kalıtım', ['X\'e bağlı baskın kalıtım', 'Otozomal çekinik kalıtım', 'Y\'ye bağlı kalıtım'], 'Hastalık mitokondriyal DNA\'daki mutasyonlardan kaynaklanır; mitokondriler yumurta sitoplazmasıyla aktarıldığından yalnız anneden geçer.'),
  ('Mısırda sitoplazmik erkek kısırlığı taşıyan hatların hibrit tohum üretiminde kullanılmasının en önemli yararı nedir?', 'Çiçeklerin elle hadımlaştırılmasına gerek bırakmaması', ['Bitkilerin daha uzun boylu olmasını sağlaması', 'Tohumların daha hızlı çimlenmesini sağlaması', 'Hibritlerin bütün özelliklerinin yalnızca anne bitkiden gelmesini sağlaması'], 'Bu hatlar işlevli polen üretmediğinden yalnız istenen erkek hattan tozlanır; püsküllerin elle koparılması gerekmez.'),
  ('Tatlı su salyangozunda (Lymnaea) kabuğun sağa ya da sola kıvrılması yavrunun kendi genotipine göre değil, annenin genotipine göre belirlenir. Bu kalıtım biçimine ne ad verilir?', 'Maternal etki', ['Mitokondriyal mutasyon', 'Eş baskınlık', 'Eşeye bağlı kalıtım'], 'Maternal etkide yumurtaya anneden konan gen ürünleri erken gelişimi yönlendirir; yavrunun fenotipi annenin genotipini yansıtır.'),
  ('Çekinik kalıtılan albinizm gösteren iki ebeveynin bütün çocuklarının normal pigmentli doğması nasıl açıklanabilir?', 'Ebeveynlerin albinizmi farklı genlerden kaynaklanıyordur', ['Çocuklarda mutasyonların gelişim sırasında kendiliğinden düzelmesi', 'Albinizmin baskın kalıtılması', 'Çocukların pigmentlerini çevreden alması'], 'Anne aaBB, baba AAbb ise çocuklar AaBb olur; her iki genin işlevli bir kopyası bulunduğundan pigment üretilir. Buna komplementasyon (tamamlama) denir.'),
  ('Bir monohibrit F2\'de 315 baskın ve 85 çekinik fenotipli birey sayılıyor. 3 : 1 beklentisine göre hesaplanan ki-kare değeri 3,0\'dır. Serbestlik derecesi 1 için kritik değer 3,84 ise en doğru yorum hangisidir?', 'Sapma şansla açıklanabilir; 3 : 1 hipotezi reddedilmez', ['Sapma anlamlıdır; 3 : 1 hipotezi kesin olarak reddedilmelidir', 'Sonuç 1 : 1 oranını kanıtlar', 'Ki-kare bu tür verilere uygulanamaz'], 'Hesaplanan değer (3,0) kritik değerden (3,84) küçük olduğu için gözlenen ile beklenen arasındaki fark istatistiksel olarak anlamlı değildir.'),
  ('Mendel bezelye deneylerinin sonuçlarını 1865\'te ilk kez nerede sözlü olarak sunmuştur?', 'Brünn Doğa Bilimleri Derneği\'nin toplantılarında', ['Londra\'daki Kraliyet Cemiyeti\'nde', 'Paris Bilimler Akademisi\'nde', 'Viyana Üniversitesi\'nin yıllık açılış töreninde verdiği konuşmada'], 'Mendel bulgularını Şubat ve Mart 1865\'te Brünn Doğa Bilimleri Derneği\'nde anlatmış, makale derneğin dergisinde 1866\'da çıkmıştır.'),
  ('İstatistikçi Ronald Fisher 1936\'da Mendel\'in verileri hakkında hangi eleştiriyi ileri sürmüştür?', 'Verilerin beklenen oranlara gereğinden fazla yakın olduğunu', ['Mendel\'in hiç bezelye yetiştirmediğini', 'Verilerin 3 : 1 oranından çok saptığını', 'Mendel\'in yalnız tek bir karakter inceleyip ötekileri uydurduğunu'], 'Fisher, şans sapmalarının beklenenden küçük olduğunu hesaplamış; bu \'fazla iyi\' sonuçların nedeni hâlâ tartışılmaktadır, ancak Mendel\'in vardığı ilkeler doğrudur.'),
  ('Meyve sineğinde X kromozomlarının ayrılmaması sonucu ortaya çıkan olağan dışı döllerin göz rengi kalıtımını açıklayarak genlerin kromozomlarda taşındığını 1916\'da kesin biçimde kanıtlayan Morgan\'ın öğrencisi kimdir?', 'Calvin Bridges', ['Alfred Sturtevant', 'Hermann Muller', 'Walter Sutton'], 'Bridges, ayrılmama ile oluşan XXY dişi ve XO erkek sineklerin fenotiplerinin kromozom içeriğiyle birebir uyduğunu göstermiştir.'),
  ('\'Homozigot\' ve \'heterozigot\' terimlerini kalıtım bilimine kazandıran, Mendel\'in görüşlerinin İngiltere\'deki öncü savunucusu kimdir?', 'William Bateson', ['Charles Darwin', 'Francis Galton', 'Thomas Hunt Morgan'], 'Bateson allelomorf (alel), homozigot ve heterozigot gibi temel terimleri 1900\'lerin başında önermiştir.'),
  ('Johannsen, kendileştirilmiş saf fasulye hatlarında en iri ve en küçük tohumları seçip ekmesine rağmen döllerin tohum ortalamasının değişmediğini gördü. Bu deneyden çıkardığı sonuç hangisidir?', 'Saf hat içindeki farkların çevresel olup seçilimle değişmediğini', ['Tohum büyüklüğünün tamamen kalıtsal olduğunu', 'Seçilimin saf hatlarda çok hızlı ve kalıcı sonuç verdiğini gösterdiğini', 'Fasulyelerde genlerin bulunmadığını'], 'Saf hattaki bitkiler aynı genotipe sahip olduğundan aralarındaki farklar çevreden kaynaklanır; bu çalışma genotip-fenotip ayrımının temelini oluşturmuştur.'),
  ('Thomas Hunt Morgan ve öğrencilerinin meyve sineği deneylerini yürüttükleri, \'sinek odası\' adıyla tanınan laboratuvar hangi üniversitededir?', 'Columbia Üniversitesi', ['Cambridge Üniversitesi', 'Viyana Üniversitesi', 'Harvard Üniversitesi'], 'Morgan\'ın New York\'taki Columbia Üniversitesi\'ndeki küçük laboratuvarı Sturtevant, Bridges ve Muller gibi genetikçileri yetiştirmiştir.'),
  ('Şeker mısırı (çekinik su aleli) tarlasının yanına nişastalı tarla mısırı ekildiğinde şeker mısırı koçanlarında bazı tanelerin nişastalı ve az tatlı çıkması nasıl açıklanır?', 'Tanelerin baskın alelli yabancı polenle döllenmesi', ['Şeker mısırının toprağı değiştirmesi', 'Nişastanın kökten koçana taşınması', 'Şeker mısırında mutasyonların sıcakla artması'], 'Tanenin besin dokusu ve embriyosu döllenmeyle oluşur; tarla mısırından gelen baskın alel bu tanelerde şekerin nişastaya dönüşmesini sağlar.'),
  ('Hastalığa dirençli yabani bir bitki seçkin bir çeşitle melezleniyor ve döller her kuşak yeniden seçkin çeşitle geri çaprazlanıyor (direnç taşıyanlar seçilerek). Seçkin çeşide ait genom payının ortalama %93,75\'e ulaşması için ilk melezden sonra kaç geri çaprazlama gerekir?', '3', ['2', '4', '6'], 'F1\'de seçkin genom %50\'dir; her geri çaprazlama kalan yabancı payı yarıya indirir: %75, %87,5, %93,75.'),
  ('Taşıyıcı iki ebeveynin (Aa × Aa) üç çocuğundan tam olarak ikisinin otozomal çekinik hastalık göstermesi olasılığı nedir?', '9/64', ['3/64', '1/16', '27/64'], 'Hasta iki çocuğun hangileri olacağı 3 biçimde seçilir: 3 × (1/4)² × 3/4 = 9/64.'),
  ('Taşıyıcı iki ebeveynin (Aa × Aa) ilk çocuğunun otozomal çekinik hastalık gösteren bir erkek, ikinci çocuğunun ise sağlıklı bir kız olma olasılığı nedir?', '3/64', ['3/16', '1/16', '9/64'], 'Hasta erkek: 1/2 × 1/4 = 1/8; sağlıklı kız: 1/2 × 3/4 = 3/8. Sıra belirlendiği için 1/8 × 3/8 = 3/64.'),
  ('Üç aleli bulunan X\'e bağlı bir gen için insan popülasyonunda (iki eşey birlikte) kaç farklı genotip bulunabilir?', '9', ['6', '3', '12'], 'Dişilerde üç alelden ikili birleşimler 6 genotip, erkeklerde tek alel 3 genotip verir: 6 + 3 = 9.'),
  ('Meyve sineğinde beyaz göz (w) X\'e bağlı, körelmiş kanat (vg) otozomal çekinik özelliklerdir. Kırmızı gözlü, normal kanatlı XʷX⁺ vg⁺vg dişi ile beyaz gözlü, normal kanatlı XʷY vg⁺vg erkek çaprazlanıyor. Döllerin kaçta kaçı beyaz gözlü ve körelmiş kanatlı bir dişi olur?', '1/16', ['1/8', '1/4', '1/32'], 'Dişi olma 1/2, dişinin beyaz gözlü olması (XʷXʷ) 1/2, körelmiş kanat (vg vg) 1/4: 1/2 × 1/2 × 1/4 = 1/16.'),
  ('X kromozomundaki iki bağlı gen arasındaki rekombinasyon sıklığını ölçmek için memelilerde hangi eşeyin gametleri incelenmelidir?', 'İki gen için heterozigot olabilen dişinin', ['Tek X taşıyan erkeğin', 'İki eşeyin gametleri eşit derecede bilgi verir', 'Hiçbir eşeyin, çünkü X\'te rekombinasyon olmaz'], 'Erkekler X bakımından hemizigot olduğundan iki X\'e bağlı gen arasında gözlenebilir rekombinasyon ancak iki X taşıyan dişide oluşur.'),
  ('Bir kadın renk körlüğü alelini X kromozomlarından birinde, hemofili alelini ise öteki X\'inde taşıyor. Bu kadının bir oğlunun hem renk körü hem hemofili olması nasıl açıklanır?', 'Yumurta oluşumunda iki X arasında krossing-over olması', ['Babadan iki alelin birden gelmesi', 'Oğlunda iki X kromozomu bulunması', 'Bu durumun kalıtım kurallarına göre kesinlikle olanaksız olması'], 'İki alel trans dizilimdedir; aralarında krossing-over olursa iki mutant aleli aynı X\'te taşıyan rekombinant bir yumurta oluşabilir.'),
  ('Alkaptonürili bebeklerin bezlerinin havayla temas ettikten sonra koyulaşması fark edilerek hastalık tanınabilir. Bunun nedeni nedir?', 'Havada kararan homogentisik asidin parçalanamayıp idrarla atılması', ['İdrarda kan bulunması', 'Bez kumaşındaki boyaların bebeğin idrarındaki bakterilerle renk değiştirmesi', 'İdrarda fazla miktarda glikoz bulunması'], 'Homogentisik asidi yıkan enzimin eksikliğinde bu madde idrarla atılır ve oksijenle tepkimeye girince koyu renk alır.'),
  ('Bağırsaktan aşırı demir emilimi sonucu karaciğer, kalp ve pankreasta demir birikmesiyle seyreden ve Kuzey Avrupa kökenlilerde sık görülen otozomal çekinik hastalık hangisidir?', 'Kalıtsal hemokromatoz', ['Hemofili', 'Akondroplazi', 'Talasemi'], 'Kalıtsal hemokromatozda demir emilimini sınırlayan düzenleme bozulur; erken tanıda düzenli kan alma tedavisiyle organ hasarı önlenebilir.'),
  ('Bakırın karaciğer ve beyinde birikmesine yol açan ve gözün kornea kenarında kahverengi-yeşil halka görülebilen otozomal çekinik hastalık hangisidir?', 'Wilson hastalığı', ['Huntington hastalığı', 'Marfan sendromu', 'Hemofili B'], 'Wilson hastalığında bakırı safraya atan taşıyıcı protein bozuktur; biriken bakır karaciğer ve sinir sistemine zarar verir.'),
  ('Mendel\'in buruşuk bezelye tohumlarında (rr) nişasta dallandırıcı enzim işlevsizdir. Bu tohumların buruşmasının en iyi açıklaması hangisidir?', 'Biriken şekerin su çekmesi ve tohum kururken büzülmesi', ['Tohum kabuğunun hiç oluşmaması', 'Tohumun hiç su almaması', 'Tohumda klorofilin parçalanmaması ve tohumun yeşil kalarak kuruması'], 'Enzim yokluğunda nişasta az, şeker çok olur; şeker osmotik olarak su çeker, tohum kurudukça bu su kaybedilir ve tohum buruşur.'),
  ('Mendel\'in yeşil bezelye tohumları, olgunlaşma sırasında klorofili parçalayan bir yolun bozuk olmasından kaynaklanır. Buna göre sarı tohum alelinin yeşile baskın olması nasıl açıklanabilir?', 'Tek işlevli alelin yeterli enzim sağlaması', ['Sarı alelin yeşil aleli kalıcı olarak bozması', 'Yeşil alelin yalnız yapraklarda ifade edilip tohumlarda hiç ifade edilmemesi', 'Sarı rengin çevre koşullarıyla oluşması'], 'Heterozigotta tek işlevli kopya klorofilin yıkılmasına yetecek ürünü sağlar; bu yüzden tohum sarı olur. Birçok çekinik alel işlev kaybına neden olur.'),
  ('Yarık damak ve yarık dudak gibi özelliklerin hem birçok gene hem çevre etkenlerine bağlı olduğu ve belirli bir yatkınlık düzeyi aşıldığında ortaya çıktığı düşünülür. Bu tür özelliklere ne ad verilir?', 'Çok etkenli eşik özellikleri', ['Y\'ye bağlı özellikler', 'Tek genli, tam baskın özellikler', 'Sitoplazmik özellikler'], 'Bu özelliklerde yatkınlık sürekli dağılır; ancak fenotip yalnız eşik aşıldığında \'var\' ya da \'yok\' biçiminde görülür.'),
  ('Otozomal baskın kalıtılan ve böbreklerde çok sayıda sıvı dolu kese oluşmasıyla genellikle yetişkinlikte belirti veren hastalık hangisidir?', 'Yetişkin tipi polikistik böbrek hastalığı', ['Kistik fibrozis', 'Fenilketonüri', 'Galaktozemi'], 'Yetişkin tipi polikistik böbrek hastalığı baskın kalıtılır ve belirtileri çoğunlukla 30–40 yaşlarında başlar.'),
  ('Ortak büyükbabaları otozomal çekinik bir hastalık için taşıyıcı olan iki birinci dereceden kuzen evleniyor (başka taşıyıcı yok). Çocuklarının bu hastalıkla doğma olasılığı nedir?', '1/64', ['1/16', '1/32', '1/8'], 'Her kuzenin taşıyıcı olma olasılığı 1/4\'tür; ikisinin de taşıyıcı olup çocuğa çekinik alel vermesi 1/4 × 1/4 × 1/4 = 1/64.'),
  ('Dört çocuklu bir ailede en az iki çocuğun kız olma olasılığı nedir?', '11/16', ['3/8', '1/2', '15/16'], 'Hiç kız olmaması 1/16, tam bir kız olması 4/16\'dır; en az iki kız 1 − 5/16 = 11/16 olur.'),
  ('1 : 1 oranı beklenen bir test çaprazlamasında 100 dölden 60\'ı baskın, 40\'ı çekinik fenotipte çıkıyor. Ki-kare değeri 4,0\'dır ve serbestlik derecesi 1 için kritik değer 3,84\'tür. Doğru yorum hangisidir?', 'Sapma anlamlıdır; 1 : 1 hipotezi reddedilir', ['Sapma yalnızca şansla açıklanır; bu yüzden hipotez reddedilmez', 'Sonuç 3 : 1 oranını kanıtlar', 'Ki-kare değeri negatif olduğu için yorum yapılamaz'], 'Ki-kare = (10²/50) + (10²/50) = 4,0; bu değer kritik değerden büyük olduğundan fark istatistiksel olarak anlamlıdır.'),
  ('AaBbCc × AaBbCc çaprazlamasının F2\'sinde (genler bağımsız) kaç farklı tam homozigot genotip bulunur?', '8', ['3', '6', '27'], 'Her lokus için iki homozigot seçenek (örneğin AA ya da aa) vardır: 2³ = 8.'),
  ('A ve B genleri aynı kromozomda tam bağlı, C geni ise farklı bir kromozomdadır. AB/ab Cc genotipli bir birey kaç çeşit gamet oluşturur?', '4', ['8', '2', '6'], 'Bağlı A–B bloğu 2 çeşit (AB, ab), bağımsız C lokusu 2 çeşit gamet verir: 2 × 2 = 4.'),
  ('Genotipi I^A I^B MN Rr olan bir anne ile ii MN rr olan bir babanın çocuklarında ABO, MN ve Rh grupları birlikte düşünüldüğünde kaç farklı kan grubu fenotipi ortaya çıkabilir?', '12', ['8', '6', '108'], 'ABO için A ve B (2), MN için M, MN, N (3), Rh için + ve − (2) fenotip vardır: 2 × 3 × 2 = 12.'),
  ('AaBb genotipli bir bitki aabb ile test çaprazlamasına sokuluyor ve 1000 döl elde ediliyor: 450 Aabb, 450 aaBb, 60 AaBb, 40 aabb. A ile B genleri arasındaki uzaklık kaç cM\'dir?', '10', ['45', '90', '6'], 'Çoğunluktaki Aabb ve aaBb ebeveyn tipidir (trans dizilim); rekombinantlar AaBb ve aabb\'dir: (60 + 40) / 1000 = %10.'),
  ('Aa × aa geri çaprazlamasından elde edilen bitkilerin her biri kendileştiriliyor. Oluşan kuşağın tamamında çekinik fenotipli bitkilerin oranı nedir?', '5/8', ['1/2', '3/8', '1/4'], 'Geri çaprazlama dölünün 1/2\'si aa (yalnız aa verir), 1/2\'si Aa\'dır (1/4 aa verir): 1/2 + 1/2 × 1/4 = 5/8.'),
  ('Bir bitki grubunun 1/3\'ü AA, 2/3\'ü Aa genotiplidir. Bu bitkilerin her biri yalnız kendi kendini döllerse döllerin kaçta kaçı çekinik fenotipli olur?', '1/6', ['1/9', '1/4', '1/3'], 'Yalnız Aa bitkiler aa döl verir: 2/3 × 1/4 = 1/6. (Rastgele çiftleşmede bu oran 1/9 olurdu.)'),
  ('Aa × Aa çaprazlamasının F2 dölünden rastgele seçilen baskın fenotipli bir bitki, çekinik bir bitkiyle test çaprazlamasına sokuluyor. Bu çaprazlamadan doğacak bir dölün çekinik fenotipli olma olasılığı nedir?', '1/3', ['1/2', '1/4', '2/3'], 'Seçilen bitkinin Aa olma olasılığı 2/3\'tür; Aa × aa\'da çekinik döl olasılığı 1/2: 2/3 × 1/2 = 1/3.'),
  ('Bir gende üç alel bulunuyor ve hepsi birbirine karşı eş baskın. Bu gen için popülasyonda kaç farklı fenotip görülebilir?', '6', ['3', '4', '9'], 'Eş baskınlıkta her genotip ayrı fenotip verir; üç alelle 3 homozigot ve 3 heterozigot olmak üzere 6 genotip, dolayısıyla 6 fenotip vardır.'),
  ('İnsanda Mendel kurallarına uygun olarak kalıtıldığı gösterilen ilk özelliklerden biri olan ve kısa parmaklılık olarak bilinen baskın özellik hangisidir?', 'Brakidaktili', ['Polidaktili', 'Albinizm', 'Hemofili'], 'William Farabee 1905\'te brakidaktilinin bir ailede baskın Mendel özelliği gibi kalıtıldığını göstermiştir.'),
  ('Krossing-overın homolog kromozomlar arasında gerçek bir fiziksel parça değişimi olduğunu 1931\'de mısırda görülebilir kromozom işaretleri kullanarak gösteren araştırmacılar kimlerdir?', 'Harriet Creighton ve Barbara McClintock', ['James Watson ve Francis Crick', 'Walter Stanborough Sutton ve Theodor Boveri', 'Hugo de Vries ve Carl Correns'], 'Creighton ve McClintock, mikroskopla ayırt edilebilen kromozom uçlarıyla genetik rekombinasyonun aynı anda gerçekleştiğini göstermiştir.'),
  ('Bateson ve Punnett 1905\'te kokulu bezelyede çiçek rengi ile polen biçiminin beklenenden çok daha sık birlikte kalıtıldığını gözlemlediler. Bu gözlem sonradan hangi olguyla açıklanmıştır?', 'Genlerin aynı kromozomda bağlı olması', ['Genlerin eşeye bağlı olması', 'Polenlerin mitokondriyal kalıtım göstermesi', 'Genlerden birinin letal olması'], 'İki karakterin ebeveyn birleşimlerinin fazla görülmesi, genlerin aynı kromozomda yakın konumda olmasından (bağlılık) kaynaklanır.'),
  ('Çoğunlukla kız çocuklarında görülen, erken çocuklukta kazanılmış becerilerin gerilemesi ve el ovuşturma hareketleriyle seyreden, X\'e bağlı baskın bir mutasyondan kaynaklanan nörogelişimsel sendrom hangisidir?', 'Rett sendromu', ['Turner sendromu', 'Down sendromu', 'Marfan sendromu'], 'Rett sendromu MECP2 genindeki mutasyonlardan kaynaklanır; erkek embriyolarda genellikle çok ağır seyrettiği için hastaların büyük çoğunluğu kızdır.'),
  ('Aa × Aa çaprazlamasının F2\'sinden rastgele iki baskın fenotipli birey seçilip birbiriyle çaprazlanıyor. Seçilen iki bireyin de heterozigot olma olasılığı nedir?', '4/9', ['1/4', '2/3', '1/9'], 'Baskın fenotipli F2 bireylerinin her birinin Aa olma olasılığı 2/3\'tür; ikisinin birden Aa olması 2/3 × 2/3 = 4/9.'),
  ('Üç karakter için heterozigot bir bitkinin kendileştirilmesinden elde edilen F2\'de fenotipler 27 : 9 : 9 : 9 : 3 : 3 : 3 : 1 oranında dağılıyor. Bu sonuç en iyi nasıl yorumlanır?', 'Bağımsız açılan, tam baskın üç gen vardır', ['Tek bir gen üç alelle bu karakterleri belirler', 'İki gen bağlı, biri bağımsızdır', 'Karakterler eklemeli tek bir genle belirlenir'], 'Bu oran (3/4 + 1/4)³ açılımıdır; üç bağımsız 3 : 1 oranının çarpımıyla 64 paylı sekiz sınıf oluşur.'),
  ('Tavuklarda R_P_ ceviz, R_pp gül, rrP_ bezelye, rrpp tek ibik verir. Rrpp gül ibikli bir horoz ile rrPp bezelye ibikli bir tavuk çiftleştirilirse civcivlerde hangi ibik biçimleri hangi oranda görülür?', '1 ceviz : 1 gül : 1 bezelye : 1 tek', ['Tamamı ceviz', '1 gül : 1 bezelye', '9 ceviz : 3 gül : 3 bezelye : 1 tek ibik'], 'Rr × rr ve pp × Pp çaprazlamalarının her biri 1 : 1 verir; birleşince RrPp, Rrpp, rrPp, rrpp eşit oranda oluşur.'),
  ('Meyve sineğinde kırmızı göz pigmentinin taşınmasında görev alan bir genin \'white\' (beyaz) olarak adlandırılmasının nedeni nedir?', 'Genlerin çoğunlukla mutant fenotipe göre adlandırılması', ['Genin yalnız beyaz pigment üretmesi', 'Genin yalnız beyaz renkli sineklerde bulunması', 'Genin X kromozomunun boyanınca beyaz görünen bölgesinde bulunması'], 'Gen, işlevini yitirdiğinde gözlerin beyaz olmasıyla tanındığı için bu adı almıştır; yabanıl alel (w⁺) kırmızı gözü sağlar.'),
  ('Bir genetik çalışmada ebeveynlerden biri belirli bir fenotip için saf döl, diğeri farklı bir fenotip için saf döldür ve F1 bireylerinin tamamı iki ebeveynden de farklı, yeni bir fenotip gösteriyor. Bu sonuç için olası açıklamalardan biri hangisidir?', 'Farklı genlerdeki alellerin F1\'de bir araya gelip etkileşmesi', ['F1 bireylerinin tümünün aynı anda mutasyon geçirmesi', 'Ebeveynlerin aslında heterozigot olması', 'Özelliğin yalnız anneden kalıtılması'], 'Örneğin gül (RRpp) ve bezelye (rrPP) ibikli tavukların F1\'i ceviz ibiklidir; iki farklı genin baskın alelleri birlikte yeni bir fenotip oluşturur. Eksik baskınlık da başka bir olası açıklamadır.'),
  ('Renk körlüğü (X\'e bağlı çekinik) bakımından taşıyıcı ve albinizm (otozomal çekinik) bakımından heterozigot bir kadın, renk körü ve albinizm bakımından heterozigot bir erkekle evleniyor. Doğacak çocuğun normal görüşlü ve normal pigmentli bir oğul olma olasılığı nedir?', '3/16', ['3/8', '1/4', '9/16'], 'Normal görüşlü oğul: 1/2 (erkek) × 1/2 (anneden normal X) = 1/4; normal pigment 3/4. Çarpım 1/4 × 3/4 = 3/16.'),
  ('Kabaklarda W_ beyaz, wwY_ sarı, wwyy yeşil meyve verir (12 : 3 : 1). F2\'deki beyaz meyveli bitkiler arasında kendileştirildiğinde yalnız beyaz meyveli döl verecek olanların oranı nedir?', '1/3', ['1/4', '1/12', '2/3'], 'Saf beyaz döl için WW gerekir; beyazların 12 payının 4\'ü (WWYY, 2 WWYy, WWyy) WW\'dir: 4/12 = 1/3.'),
  ('Kokulu bezelyede mor çiçek için C_P_ gerekir; F2\'de 9 mor : 7 beyaz görülür. F2\'deki beyaz çiçekli bitkilerin kaçta kaçı iki gen bakımından da homozigot çekiniktir (ccpp)?', '1/7', ['1/16', '3/7', '1/9'], 'Beyazların 7 payından yalnız biri ccpp\'dir; diğerleri C_pp (3) ve ccP_ (3) genotiplidir.'),
  ('Çoban çantasında iki genden en az birinde baskın alel bulunması üçgen kapsül verir (15 : 1). F2\'deki üçgen kapsüllü bitkilerin kaçta kaçı kendileştirildiğinde hiç oval döl vermez?', '7/15', ['1/15', '4/15', '8/15'], 'Oval döl çıkmaması için en az bir lokusun homozigot baskın olması gerekir: AA__ (4) + __BB (4) − AABB (1) = 7 pay; 7/15.'),
  ('Üç bağlı gen (A–B–C) için yapılan 1000 döllük bir test çaprazlamasında A–B bölgesinde tek krossing-over gösteren 150, B–C bölgesinde tek krossing-over gösteren 90 ve çift krossing-over gösteren 10 döl bulunuyor. A ile B arasındaki uzaklık kaç cM\'dir?', '16', ['15', '25', '10,5'], 'A–B uzaklığı, bu bölgede krossing-over geçiren bütün döllerden hesaplanır: (150 + 10) / 1000 = %16.'),
  ('Darwin\'in, vücudun her bölümünden salgılanan küçük taneciklerin (gemmüller) eşey hücrelerinde toplanarak kalıtımı sağladığını öne süren ve sonradan çürütülen hipotezinin adı nedir?', 'Pangenezis', ['Preformasyon', 'Epigenez', 'Biyogenez'], 'Darwin 1868\'de pangenezis hipotezini önermişti; Mendel genetiği ve Weismann\'ın germ plazması kuramı bu görüşün yerini aldı.'),
  ('Beyaz kamp çiçeği (Silene latifolia) gibi bazı iki evcikli bitkilerde erkek bireyler XY, dişi bireyler XX kromozomludur. Bu bilgi eşey belirleme hakkında neyi gösterir?', 'Kromozomal eşey belirlemenin bazı bitkilerde de olduğunu', ['Bütün bitkilerde eşeyin sıcaklıkla belirlendiğini', 'Bitkilerde eşey kromozomu bulunmasının olanaksız olduğunu', 'Bu bitkilerde erkeklerin döllenmemiş yumurtadan geliştiğini'], 'Çiçekli bitkilerin çoğu erselik olsa da bazı iki evcikli türlerde memelilere benzeyen XY eşey belirleme sistemi gelişmiştir.'),
  ('Otozomal çekinik bir hastalığı olan bir kişinin sağlıklı kardeşi (anne ve baba sağlıklı), bu hastalığa yakalanmış biriyle evleniyor. Çocuklarının hasta olma olasılığı nedir?', '1/3', ['1/2', '1/4', '1/6'], 'Sağlıklı kardeşin taşıyıcı olma olasılığı 2/3\'tür; taşıyıcı × hasta çaprazlamasında çocuk 1/2 olasılıkla hastadır: 2/3 × 1/2 = 1/3.'),
  ('Taşıyıcı (Aa) iki ebeveynin hasta olmayan bir çocuğu, taşıyıcı olmadığı kesin olarak bilinen (AA) biriyle evleniyor. Bu evlilikten doğacak çocukların taşıyıcı olma olasılığı nedir?', '1/3', ['1/2', '1/4', '2/3'], 'Sağlıklı çocuğun taşıyıcı olma olasılığı 2/3\'tür; taşıyıcıysa çocuğuna a alelini 1/2 olasılıkla verir: 2/3 × 1/2 = 1/3.'),
  ('Eklemeli iki gen çiftinin belirlediği bir özellikte aabb bireyler 10 cm, her eklemeli alel 4 cm ekliyor. AABb × aaBb çaprazlamasından doğan bireyler hangi boylarda olabilir?', '14, 18 ve 22 cm', ['10, 14 ve 18 cm', '14 ve 18 cm', '18, 22 ve 26 cm boylarında'], 'Döller her zaman AABb ebeveynden A, aaBb ebeveynden a alır (1 eklemeli alel); B lokusu 0, 1 ya da 2 eklemeli alel ekler. Toplam 1–3 alel: 14, 18, 22 cm.'),
  ('Mitokondriyal kalıtım ile maternal etki arasındaki fark hangi seçenekte doğru verilmiştir?', 'Birinde mitokondri DNA\'sı, ötekinde annenin çekirdek genleri belirleyicidir', ['İkisinde de özellik babanın genotipiyle belirlenir', 'Maternal etkide genler mitokondride, mitokondriyal kalıtımda çekirdektedir', 'İkisi aynı olgunun farklı ders kitaplarında kullanılan iki ayrı adıdır'], 'Maternal etkide yumurtaya annenin çekirdek genlerinin ürünleri konur; mitokondriyal kalıtımda ise genler mitokondri DNA\'sındadır ve yalnız anneden gelir.'),
  ('Soyağacı şemalarında tek yumurta ikizleri nasıl gösterilir?', 'Tek noktadan çıkan, yatay çizgiyle birleşen iki dal ile', ['Birbirinden ayrı iki dikey çizgi ile', 'İçi yarı boyalı iki simge ile', 'Çift yatay çizgiyle birbirine bağlanmış ve içi boyalı iki simge ile'], 'İkizler ebeveyn hattındaki tek bir noktadan çıkan iki dalla gösterilir; tek yumurta ikizlerinde bu iki dal ayrıca yatay bir çizgiyle birleştirilir.'),
  ('Heterozigot A (I^A i) kan gruplu bir anne ile heterozigot B (I^B i) kan gruplu bir babanın dört çocuğunun her birinin farklı bir kan grubundan olma olasılığı nedir?', '3/32', ['1/256', '1/4', '1/24'], 'Dört kan grubunun her biri 1/4 olasılıklıdır; dört farklı grubun dört çocuğa 4! = 24 farklı sırada dağılması mümkündür: 24 × (1/4)⁴ = 24/256 = 3/32.'),
  ('I^A i × I^B i çiftinin iki çocuğunun aynı kan grubundan olma olasılığı nedir?', '1/4', ['1/16', '1/2', '3/4'], 'Her kan grubu 1/4 olasılıklıdır; iki çocuğun aynı grupta olması 4 × (1/4 × 1/4) = 1/4 eder.'),
  ('Aşağıdaki örneklerden hangisi baskın epistasiye (bir genin baskın alelinin başka bir genin etkisini maskelemesi) örnektir?', 'Kabakta tek W alelinin beyaz meyve oluşturması', ['Labradorlarda ee genotipinin sarı renge yol açması', 'Farelerde cc genotipinin albinizme yol açması', 'İnsanda hh genotipinin Bombay fenotipine yol açması'], 'Labrador, fare ve Bombay örneklerinde maskeleme çekinik homozigotlukla olur (çekinik epistasi); kabakta ise tek bir W aleli yeterlidir.'),
  ('Bal arılarında kraliçenin kızları olan işçi arılar, aynı erkek arıdan geliyorsa birbirleriyle ortalama ne oranda akrabadır?', '3/4', ['1/2', '1/4', '1/8'], 'Kız kardeşler babadan (haploit erkek) özdeş genleri alır (1/2 pay), anneden aldıkları genlerin ise yarısı ortaktır (1/4 pay): toplam 3/4.'),
  ('Belçika mavisi sığırlarında görülen aşırı kas gelişimi, kas büyümesini sınırlayan bir proteinin işlev kaybına uğramasından kaynaklanır. Bu protein hangisidir?', 'Miyostatin', ['Miyoglobin', 'Aktin', 'Tropomiyozin'], 'Miyostatin kas büyümesini frenler; genindeki işlev kaybı mutasyonları homozigot hayvanlarda \'çift kaslılık\' fenotipine yol açar.'),
  ('İki farklı otozomal çekinik hastalık için taşıyıcı olan (AaBb) iki ebeveynin çocuğunun bu hastalıklardan en az birine yakalanma olasılığı nedir (genler bağımsız)?', '7/16', ['1/16', '1/2', '3/8'], 'İki hastalıktan da korunma olasılığı 3/4 × 3/4 = 9/16\'dır; en az birine yakalanma 1 − 9/16 = 7/16 olur.'),
  ('Pıhtılaşma faktörü IX\'un eksikliğinden kaynaklanan ve \'Christmas hastalığı\' olarak da bilinen kalıtsal hastalık hangisidir?', 'Hemofili B', ['Hemofili A', 'Von Willebrand hastalığı', 'Talasemi'], 'Hemofili B, ilk tanımlanan hastanın soyadından ötürü Christmas hastalığı olarak da anılır; hemofili A gibi X\'e bağlı çekinik kalıtılır.'),
  ('Doğuştan işitme kaybının, farklı ailelerde onlarca farklı genden herhangi birindeki çekinik mutasyonlarla ortaya çıkabilmesine ne ad verilir?', 'Lokus (genetik) heterojenliği', ['Alelik eşitlik', 'Eş baskınlık', 'Pleiotropi'], 'Aynı fenotipin farklı lokuslardaki mutasyonlarla oluşmasına lokus heterojenliği denir; bu yüzden işitme engelli iki ebeveynin işiten çocukları olabilir.'),
  ('Kistik fibrozise yol açan CFTR geninde binden fazla farklı mutasyonun tanımlanmış olması hangi kavramla ifade edilir?', 'Alelik heterojenlik', ['Lokus heterojenliği', 'Epistasi', 'Değişken penetrans ve ekspresivite'], 'Aynı gende farklı mutasyonların (farklı alellerin) benzer hastalığa yol açmasına alelik heterojenlik denir.'),
  ('Mendel\'in bezelye çalışmaları dışında ilgilendiği ve düzenli kayıtlar tuttuğu alanlardan biri hangisidir?', 'Meteorolojik gözlemler ve arıcılık', ['Elektrik devreleri', 'Kuyruklu yıldızların yörüngeleri', 'Deniz canlılarının sınıflandırılması'], 'Mendel uzun yıllar hava durumu ölçümleri yapmış ve arılarla melezleme denemelerine girişmiştir.'),
  ('Bezelyede tohum kabuğu anne bitkinin dokusundan gelişir. Tohum kabuğu rengi gibi bir özellik için heterozigot F1 bitkiler kendileştirildiğinde 3 : 1 açılım ne zaman gözlenir?', 'Bir kuşak gecikmeyle, F2 bitkilerinin tohumlarında', ['F1 bitkisinin üzerindeki tohumlarda hemen ve 1 : 2 : 1 oranında', 'Hiçbir kuşakta gözlenmez', 'Yalnız F1 bitkilerinin yapraklarında'], 'Kabuk anne dokusu olduğundan bir tohumun kabuk rengi onu taşıyan bitkinin genotipini yansıtır; F2 genotiplerinin açılımı ancak F2 bitkileri tohum verdiğinde görülür.'),
  ('Akondroplazinin hemen hemen bütün olgularında aynı gendeki (FGFR3) aynı nokta mutasyonu bulunur. Bu gen hangi dokunun büyümesini düzenleyen bir reseptörü kodlar?', 'Kıkırdak ve uzun kemiklerin büyüme plağı', ['Kalp kası', 'Retina', 'Böbrek tüpçükleri ve toplayıcı kanallar'], 'FGFR3 kıkırdak hücrelerinin çoğalmasını frenler; baskın mutasyon reseptörü aşırı etkin yaparak uzun kemiklerin büyümesini kısıtlar.'),
  ('Aa × Aa çaprazlamasından elde edilen beş yavrudan tam olarak üçünün baskın, ikisinin çekinik fenotipli olma olasılığı nedir?', '135/512', ['27/64', '45/512', '405/1024'], 'Üç baskın yavrunun seçimi 10 biçimde yapılır: 10 × (3/4)³ × (1/4)² = 270/1024 = 135/512.'),
  ('AaBbCc × AaBbCc çaprazlamasında (genler bağımsız) döllerin kaçta kaçı üç lokustan tam olarak ikisinde heterozigottur?', '3/8', ['1/8', '1/4', '3/64'], 'Her lokusta heterozigot olma olasılığı 1/2\'dir; hangi ikisinin heterozigot olacağı 3 biçimde seçilir: 3 × (1/2)³ = 3/8.'),
  ('AaBb × aaBb çaprazlamasında (genler bağımsız, baskınlık tam) döllerin kaçta kaçı ebeveynlerinin hiçbirinde görülmeyen bir fenotip gösterir?', '1/4', ['1/8', '3/8', '1/2'], 'Ebeveyn fenotipleri A_B_ ve aaB_\'dir; yeni fenotipler A_bb (1/8) ve aabb (1/8) olup toplam 1/4 eder.'),
  ('Tavşanlarda C (tam renkli) > c^ch (şinşila) > c^h (himalaya) > c (albino) baskınlık sırası geçerlidir. C c^h genotipli bir tavşan c^ch c genotipli bir tavşanla çiftleşirse yavrularda fenotip oranı ne olur?', '2 tam renkli : 1 şinşila : 1 himalaya', ['1 tam renkli : 1 şinşila : 1 himalaya : 1 albino', '1 tam renkli : 2 şinşila : 1 albino', '3 tam renkli : 1 albino'], 'Yavrular C c^ch, C c (tam renkli), c^h c^ch (şinşila) ve c^h c (himalaya) olur.'),
  ('Kuşlarda Z kromozomuna bağlı çekinik bir özellik gösteren bir tavuk (dişi), bu özellik için normal homozigot bir horozla çiftleşiyor. Civcivler için hangisi beklenir?', 'Erkek civcivler taşıyıcı, dişi civcivler normal olur', ['Dişi civcivlerin tümü özelliği gösterir', 'Erkek civcivlerin tümü özelliği gösterir, dişiler taşıyıcı olur', 'Civcivlerin yarısı özelliği gösterir'], 'Dişi (ZᵃW) Z\'sini oğullarına verir, oğullar ZᴬZᵃ (taşıyıcı) olur; kızlar Z\'yi babadan (Zᴬ) aldığı için normaldir.'),
  ('Bir kadının X\'e bağlı çekinik bir hastalık için taşıyıcı olma olasılığı başlangıçta 1/2 olarak hesaplanmıştır. Bu kadının sağlıklı bir oğlu doğduğu öğrenilince taşıyıcı olma olasılığı yeniden hesaplanırsa kaç bulunur?', '1/3', ['1/2', '1/4', '2/3'], 'Taşıyıcıysa sağlıklı oğul olasılığı 1/2, değilse 1\'dir. (1/2 × 1/2) / (1/2 × 1/2 + 1/2 × 1) = (1/4) / (3/4) = 1/3.'),
  ('Ekmek küfü Neurospora gibi yaşam döngüsünün büyük bölümünü haploit geçiren bir canlıda bir mutasyonun etkisi neden hemen fenotipte görülür?', 'Çekinik aleli örtecek ikinci bir alelin bulunmaması', ['Haploit canlılarda bütün mutasyonların kendiliğinden baskın hâle geçmesi', 'Haploit canlılar mutasyona uğramadığı için', 'Haploit canlılarda fenotip çevreyle belirlendiği için'], 'Haploit bireyde genotip doğrudan fenotipe yansır; baskınlık kavramı ancak iki alelin bir arada bulunduğu diploit evrede anlam kazanır.'),
  ('Yalnız gözlerin pigmentasyonunu etkileyen ve çoğunlukla erkeklerde görülen oküler albinizmin en yaygın tipinin kalıtım biçimi hangisidir?', 'X\'e bağlı çekinik', ['Otozomal baskın', 'Y\'ye bağlı', 'Mitokondriyal'], 'Oküler albinizm tip 1, X kromozomundaki GPR143 genindeki mutasyonlardan kaynaklanır; bu nedenle başlıca erkekleri etkiler.'),
  ('AaBb × AaBb çaprazlamasının F2\'sinden rastgele seçilen iki çift baskın fenotipli birey birbiriyle çaprazlanıyor (genler bağımsız). Bu çaprazlamadan aabb genotipli bir döl doğma olasılığı nedir?', '1/81', ['1/16', '1/9', '16/81'], 'Çift baskın fenotiplilerin AaBb olma olasılığı 4/9\'dur; iki birey de AaBb olmalı ve döl aabb olmalı: (4/9)² × 1/16 = 1/81.'),
  ('AaBb × AaBb çaprazlamasının F2\'sinden rastgele seçilen bir birey aabb ile test çaprazlamasına sokuluyor. Bu test çaprazlamasında dört farklı fenotipin birden görülebilmesi olasılığı nedir?', '1/4', ['9/16', '1/16', '1/2'], 'Dört fenotip ancak test edilen birey AaBb ise ortaya çıkar; F2\'de AaBb olma olasılığı 4/16 = 1/4\'tür.'),
  ('Bezelyede tohumun düz ya da buruşuk olması, F1 bitkileri kendileştirildiğinde F1 bitkisinin üzerindeki baklalarda hemen 3 : 1 açılım gösterir. Tohum kabuğu renginden farklı olarak bunun nedeni nedir?', 'Kotiledonların yeni dölün (F2) dokusu olması', ['Tohum biçiminin anne bitkinin genotipiyle belirlenmesi', 'Tohum biçiminin çevre tarafından belirlenmesi', 'Tohum biçimi geninin X\'e bağlı olması'], 'Kotiledonlar embriyoya aittir ve F2 genotipini taşır; tohum kabuğu ise anne dokusu olduğundan kabuk özelliklerinin açılımı bir kuşak gecikir.'),
  ('Akraba evliliğinin otozomal baskın bir hastalığın çocuklarda görülme riskini neden belirgin biçimde artırmadığı söylenebilir?', 'Tek alel yeterli olduğundan risk ebeveynin hasta olmasına bağlıdır', ['Baskın aleller akraba evliliklerinde kaybolduğu için', 'Baskın hastalıklar yalnız erkeklerde görüldüğü için', 'Akraba evliliklerinde çocuklar hep homozigot çekinik olduğu için'], 'Akraba evliliği aynı çekinik alelin iki kopyasının birleşme olasılığını artırır; baskın hastalıkta ise hasta bir ebeveynin bulunması belirleyicidir.'),
  ('X\'e bağlı çekinik bir hastalık için taşıyıcı bir kadın sağlıklı bir erkekle evli. Cinsiyetleri önceden bilinmeyen üç çocuklarının hiçbirinin hasta olmama olasılığı nedir?', '27/64', ['1/8', '1/64', '37/64'], 'Bir çocuğun hasta olması için hem oğul olması hem de anneden hastalık alelini alması gerekir: 1/2 × 1/2 = 1/4. Üç çocuğun da sağlıklı olması (3/4)³ = 27/64.'),
  ('Kendileştirilmiş saf mısır hatlarının melezlenmesiyle yüksek verimli hibrit mısır elde edilebileceğini 1908 dolaylarında gösteren Amerikalı genetikçi kimdir?', 'George Harrison Shull', ['Luther Burbank', 'Norman Ernest Borlaug', 'Barbara McClintock'], 'Shull, kendileştirmenin mısırda verimi düşürdüğünü, saf hatların melezlenmesinin ise melez azmanlığıyla verimi artırdığını göstermiştir.'),
  ('İnsanda tek gen kalıtımı gösteren özellik ve hastalıkları derleyen, Victor McKusick\'in başlattığı çevrim içi katalog hangisidir?', 'OMIM', ['GenBank', 'PubMed', 'Protein Veri Bankası'], 'OMIM, insan genleri ve Mendel kalıtımı gösteren bozukluklar hakkında bilgileri bir araya getiren temel başvuru kaynağıdır.'),
  ('Aa × Aa çaprazlamasından doğan iki yavrunun aynı genotipte olma olasılığı nedir?', '3/8', ['1/4', '1/2', '5/8'], 'İkisinin de AA (1/16), ikisinin de Aa (1/4) ya da ikisinin de aa (1/16) olma olasılıkları toplanır: 1/16 + 4/16 + 1/16 = 6/16 = 3/8.'),
  ('Bombay fenotipli (hh), ABO genotipi I^A I^B olan bir kadın, HH ii genotipli 0 grubu bir erkekle evleniyor. Çocuklarının ABO testindeki kan grubu ne olur?', 'A ya da B', ['Yalnız 0', 'Yalnız AB', 'Bombay fenotipi'], 'Çocuklar babadan H alarak Hh olur ve H maddesini yapabilir; anneden I^A ya da I^B, babadan i aldıkları için A ya da B grubu görülür.'),
  ('İki eklemeli gen çiftinin belirlediği bir özellikte tam olarak iki eklemeli alel taşıyan (orta fenotipli) kaç farklı genotip vardır?', '3', ['1', '2', '6'], 'İki büyük harfli alel AAbb, aaBB ve AaBb genotiplerinde bulunur; bu üç genotip aynı fenotipi verir.'),
  ('İnsanda 45,X kromozomlu bireyler dişi gelişirken meyve sineğinde XO bireyler nasıl bir fenotip gösterir?', 'Kısır erkek', ['Doğurgan dişi', 'Doğurgan erkek', 'Hem dişi hem erkek özellikli'], 'Meyve sineğinde eşeyi X : otozom oranı belirler; tek X\'li sinek erkek gelişir, ancak Y\'deki doğurganlık genleri olmadığından kısırdır.'),
  ('Pek çok çekinik alelin işlevsiz bir protein üretmesine rağmen heterozigotların normal fenotip göstermesi hangi kavramla açıklanır?', 'Tek işlevli kopyanın yetmesi', ['Çekinik alelin baskın alele dönüşmesi', 'Heterozigotta iki alelin de susturulması', 'Proteinin yalnız erkeklerde ve belirli gelişim evrelerinde gerekli olması'], 'Birçok enzim için normal miktarın yarısı yeterlidir; bu yüzden işlev kaybı mutasyonları çoğunlukla çekinik davranır.'),
  ('Bazı baskın kalıtsal hastalıklarda heterozigot bireylerde tek normal alel bulunduğu hâlde hastalık ortaya çıkar, çünkü bu alelin ürettiği protein miktarı yetmez. Bu duruma ne ad verilir?', 'Haplo-yetersizlik', ['Haplo-yeterlilik', 'Eş baskınlık', 'Değişken ekspresivite'], 'Haplo-yetersizlikte normal işlev için iki kopyanın ürünü gerekir; tek kopyanın yetersiz kalması baskın fenotipe yol açar.'),
  ('Farelerde t-haplotipini heterozigot taşıyan erkeklerin spermlerinin %90\'dan fazlasının bu kromozomu taşıması, Mendel\'in hangi varsayımından sapmayı gösterir?', 'İki alelin gametlere eşit oranda geçtiği varsayımından', ['Genlerin kromozomlarda taşındığı varsayımından', 'Baskın alelin fenotipte görüldüğü varsayımından', 'Kromozom sayısının türde sabit olduğu ve mayozda yarıya indiği varsayımından'], 'Ayrılma bozulması (mayotik itki) denen bu olayda bir alel gametlere beklenenden çok daha sık aktarılır ve 1 : 1 oranı bozulur.'),
  ('Babası normal görüşlü, annesi renk körlüğü taşıyıcısı olan bir erkek çocuk renk körüdür ve karyotipi 47,XXY\'dir. Bu çocuğun iki X kromozomu da renk körlüğü alelini taşıdığına göre ayrılmama büyük olasılıkla nerede gerçekleşmiştir?', 'Annede, mayoz II sırasında', ['Babada, mayoz I sırasında', 'Annede, mayoz I sırasında', 'Babada, mayoz II sırasında'], 'Babanın X\'i normal alel taşıdığından iki Xᵃ anneden gelmiştir; aynı aleli taşıyan iki kopya, kardeş kromatitlerin mayoz II\'de ayrılmamasıyla oluşur.'),
  ('Aa × Aa çaprazlamasından doğan üç yavrunun üçünün de aynı fenotipte olma olasılığı nedir?', '7/16', ['27/64', '1/64', '3/4'], 'Üçünün de baskın (27/64) ya da üçünün de çekinik (1/64) olma olasılıkları toplanır: 28/64 = 7/16.'),
  ('İnsan genomunda ortalama olarak 1 santimorganlık genetik uzaklık yaklaşık ne kadar fiziksel uzaklığa karşılık gelir?', 'Yaklaşık 1 milyon baz çifti', ['Yaklaşık 10 baz çifti', 'Yaklaşık 1000 baz çifti', 'Yaklaşık 1 milyar baz çifti'], 'İnsanda ortalama olarak 1 cM ≈ 1 Mb kabul edilir; ancak bu oran kromozom bölgelerine göre değişir.'),
  ('İnsanda aynı iki gen arasındaki rekombinasyon sıklığının yumurta ve sperm oluşumunda farklı ölçülebilmesi neyi gösterir?', 'Krossing-over sıklığının eşeye göre değişebildiğini', ['Genlerin kadınlarda başka kromozomlarda ve farklı sırayla bulunduğunu', 'Erkeklerde mayoz olmadığını', 'Rekombinasyonun yalnız X kromozomunda olduğunu'], 'İnsanda genetik haritanın toplam uzunluğu kadınlarda erkeklerdekinden belirgin biçimde daha uzundur; krossing-over sıklığı eşeyler arasında farklıdır.'),
  ('Bir pigmentin A → B → C şeklinde iki enzimle sentezlendiği bir yolda birinci enzimin geni işlevsiz olursa ikinci enzimin geni ne olursa olsun pigment oluşmaz. Bu durumda hangi gen hangisine epistatiktir?', 'Birinci basamağın geni ikinci basamağın genine epistatiktir', ['İkinci basamağın geni birinci basamağın genine epistatiktir, çünkü son ürünü o yapar', 'İki gen birbirine eş baskındır', 'Genler arasında etkileşim yoktur'], 'Yolun önceki basamağı bozulursa sonraki basamağın enzimi işleyecek madde bulamaz; önceki basamağın geni sonrakinin etkisini maskeler.'),
  ('Doku uyumunu belirleyen HLA genleri bir kromozomda birbirine yakın dizilmiş bir blok (haplotip) hâlinde kalıtılır. Aynı anne ve babanın iki çocuğunun HLA haplotiplerinin tamamen aynı olma olasılığı nedir?', '1/4', ['1/2', '1/16', '1'], 'Her ebeveyn iki haplotipinden birini verir; ikinci çocuğun ilk çocukla annenden ve babadan aynı haplotipi alma olasılığı 1/2 × 1/2 = 1/4\'tür.'),
  ('İki saf hattın melezlenmesiyle elde edilen F1 bitkileri arasında boy bakımından küçük farklar gözleniyor. Bu farkların kaynağı büyük olasılıkla nedir?', 'Çevre; F1 bireyleri genetik olarak özdeştir', ['F1 bireylerindeki farklı alel birleşimleri', 'F1 bireylerinde mayozda oluşan rekombinasyon', 'F1 bireylerinin farklı kromozom sayılarına sahip olması'], 'İki saf hattın melezleri aynı genotipe sahiptir; aralarındaki fenotip farkı yalnız çevreden kaynaklanabilir. Genetik çeşitlilik F2\'de ortaya çıkar.'),
  ('Tavuklarda renk için C_ gerekir, ancak baskın I aleli rengi baskılar (F2\'de 13 beyaz : 3 renkli). IiCc genotipli beyaz bir tavuk iicc ile çiftleştirilirse yavrularda beyaz : renkli oranı ne olur?', '3 : 1', ['1 : 1', '13 : 3', '1 : 3'], 'Yavrular IiCc, Iicc, iiCc, iicc olur; yalnız iiCc renklidir, diğer üçü beyazdır.'),
  ('Yazlık kabakta A_B_ disk, A_bb ve aaB_ küre, aabb uzun meyve verir (9 : 6 : 1). F2\'deki küre meyveli bitkilerin kaçta kaçı her iki lokusta homozigottur?', '1/3', ['1/6', '2/3', '1/2'], 'Küre meyvelilerin 6 payından AAbb ve aaBB olanlar birer paydır; 2/6 = 1/3.'),
  ('Labrador köpeklerinde B_E_ siyah, bbE_ kahverengi, __ee sarıdır. BbEe genotipli siyah bir köpek bbEe genotipli kahverengi bir köpekle çiftleşirse yavrularda siyah : kahverengi : sarı oranı nedir?', '3 : 3 : 2', ['9 : 3 : 4', '1 : 1 : 2', '9 : 3 : 3 : 1'], 'Siyah 1/2 × 3/4 = 3/8, kahverengi 1/2 × 3/4 = 3/8, sarı 1/4 = 2/8 olur.'),
  ('Eklemeli üç gen çiftinin belirlediği bir özellikte AaBbCc × AaBbCc çaprazlamasından doğanların kaçta kaçı tam olarak üç eklemeli alel taşır?', '5/16', ['1/8', '3/8', '20/27'], 'Altı alelden üçünün eklemeli olduğu birleşim sayısı 20\'dir: 20 × (1/2)⁶ = 20/64 = 5/16.'),
  ('Boyun eklemeli iki gen çiftiyle belirlendiği bir modelde AaBb genotipli orta boylu iki ebeveynin çocuklarının kaçta kaçının her iki ebeveynden de daha uzun olması beklenir?', '5/16', ['1/16', '1/4', '3/8'], 'Ebeveynlerden uzun olmak için üç ya da dört eklemeli alel gerekir: 4/16 + 1/16 = 5/16.'),
  ('Mitokondriyal hastalıklarda belirtilerin ancak bir dokudaki mutant mitokondri oranı belirli bir düzeyi aştığında ortaya çıkması hangi kavramla açıklanır?', 'Eşik etkisi', ['Eş baskınlık', 'Eşeye sınırlı kalıtım', 'Bağımsız açılım'], 'Hücrede normal mitokondriler yeterli enerjiyi sağladığı sürece belirti görülmez; mutant oranı eşiği aşınca enerji açığı belirti oluşturur.'),
  ('Çiçekli bitkilerin çoğunda kloroplastlar anneden kalıtılırken çamlar gibi bazı açık tohumlularda kloroplast DNA\'sının polenle babadan geçtiği bilinmektedir. Bu bilgi sitoplazmik kalıtımla ilgili neyi gösterir?', 'Organel kalıtımının yönünün türe göre değişebildiğini', ['Kloroplastların hiç kalıtılmadığını', 'Kloroplast genlerinin mayozda homologlar gibi ayrılıp bağımsız açıldığını', 'Açık tohumluların kloroplast taşımadığını'], 'Organel DNA\'sı genellikle tek ebeveynden geçer; hangi ebeveynin olacağı türe göre farklıdır.'),
  ('Krossing-over hesaba katılmazsa, aynı anne ve babadan doğan iki kardeşin (tek yumurta ikizi olmayan) ebeveynlerinden tam olarak aynı kromozom birleşimini alma olasılığı nedir (n = 23)?', '(1/2)⁴⁶', ['(1/2)²³', '1/46', '1/4'], 'Her ebeveyn 2²³ farklı kromozom birleşimi verebilir; ikinci çocuğun anneden ve babadan birincisiyle aynı birleşimi alma olasılığı (1/2)²³ × (1/2)²³ = (1/2)⁴⁶\'dır.'),
  ('Mendel\'in bezelyelerinde çiçeklerin gövde üzerindeki konumu bakımından baskın olan özellik hangisidir?', 'Çiçeklerin yaprak koltuklarında dizilmesi', ['Çiçeklerin yalnız gövdenin ucunda bir küme hâlinde toplanması', 'Çiçeklerin köke yakın açması', 'Çiçeklerin yalnız gece açması'], 'Aksiyal (yaprak koltuğunda) çiçek konumu, terminal (uçta) konuma baskındır.'),
  ('Mendel\'in bezelyelerinde bakla biçimi bakımından baskın olan özellik hangisidir?', 'Şişkin (dolgun) bakla', ['Boğumlu (daralmış) bakla', 'Kıvrık ve yassı bakla', 'Tüylü bakla'], 'Şişkin bakla biçimi, tohumların arasında daralan boğumlu baklaya baskındır.'),
  ('Kistik fibrozis için taşıyıcı iki ebeveynin iki çocuğundan birinin hasta, ötekinin sağlıklı taşıyıcı olma olasılığı (sıra önemsiz) nedir?', '1/4', ['1/8', '1/2', '3/16'], 'Hasta (1/4) ve taşıyıcı (1/2) birleşimi iki sırayla gerçekleşebilir: 2 × 1/4 × 1/2 = 1/4.'),
  ('Kemik iliği nakli olan bir hastanın kanında artık vericinin kan grubu saptanmaktadır. Bu hastanın çocuklarına aktaracağı ABO alelleri hangileridir?', 'Hastanın kendi eşey hücrelerindeki aleller', ['Vericinin alelleri', 'Hem vericinin hem hastanın alelleri karışık olarak', 'Hiçbir ABO aleli aktarılmaz'], 'Nakil yalnız kan yapımcı hücreleri değiştirir; yumurta ya da sperm üreten hücreler hastaya aittir ve onun genotipini taşır.'),
  ('Bir lokusta üç alel, bağımsız başka bir lokusta iki alel bulunan diploit bir türde bu iki lokus bakımından popülasyonda en fazla kaç farklı genotip olabilir?', '18', ['5', '9', '36'], 'Üç alelli lokusta 6, iki alelli lokusta 3 genotip vardır; bağımsız lokuslar için 6 × 3 = 18.'),
  ('İnsanda iki aleli olan X\'e bağlı bir gen ile iki aleli olan otozomal bir gen birlikte düşünüldüğünde popülasyonda (iki eşey birlikte) kaç farklı genotip bulunabilir?', '15', ['9', '10', '6'], 'X\'e bağlı gen için 5 (3 dişi + 2 erkek), otozomal gen için 3 genotip vardır: 5 × 3 = 15.'),
  ('Genetik danışmanlıkta soyağacının çıkarılmasını isteyen ve kendisi hasta olmayabilen başvuru sahibine ne ad verilir?', 'Danışan', ['Proband', 'Taşıyıcı', 'Kurucu birey'], 'Danışan, genetik danışmanlığa başvuran kişidir; proband ise ailede hastalık nedeniyle ilk dikkat çeken bireydir. Bu ikisi aynı kişi olmayabilir.'),
  ('Birinci dereceden kuzenlerin çocuğunda herhangi bir lokustaki iki alelin ortak atadan gelen aynı alelin kopyaları olma olasılığı (akrabalı yetiştirme katsayısı) nedir?', '1/16', ['1/8', '1/4', '1/64'], 'Kuzenler genlerinin 1/8\'ini paylaşır; çocuğun her iki alelinin de aynı ata alelinden gelme olasılığı bunun yarısı, yani 1/16\'dır.'),
  ('Meyve sineği genetiğinde \'Curly\' (kıvrık kanat) mutasyonunun sembolünün büyük harfle (Cy) yazılması neyi gösterir?', 'Mutant alelin yabanıl tipe göre baskın olduğunu', ['Mutant alelin X kromozomunda olduğunu', 'Mutasyonun ölümcül olmadığını', 'Alelin yalnız erkeklerde bulunduğunu'], 'Meyve sineği adlandırmasında baskın mutasyonlar büyük harfle, çekinik mutasyonlar küçük harfle başlar.'),
  ('Gametofitik kendine uyuşmazlık gösteren bir bitkide S1S2 genotipli dişicik başına S1S3 genotipli bir bitkinin polenleri konuyor. Hangi polenler döllenmeyi gerçekleştirebilir ve döller hangi genotipte olur?', 'Yalnız S3 polenleri; döller S1S3 ya da S2S3 olur', ['Yalnız S1 polenleri; döller S1S1 olur', 'Bütün polenler; döller S1S1, S1S2, S1S3 ve S2S3 olur', 'Hiçbir polen döllenme yapamaz'], 'Bu sistemde polen, dişicikteki alellerden biriyle aynı S alelini taşıyorsa reddedilir; S1 polenleri durur, S3 polenleri döllenir.'),
  ('Kokulu bezelyede mor çiçek için C_P_ gerekir. CcPp genotipli mor F1 bitkisi, CCpp genotipli beyaz ebeveyniyle geri çaprazlanırsa döllerde mor : beyaz oranı ne olur?', '1 : 1', ['3 : 1', '1 : 3', '9 : 7'], 'Döllerin hepsi C_ olur; P lokusunda Pp × pp 1/2 Pp verir. Mor için ikisi de gerektiğinden döllerin yarısı mor, yarısı beyazdır.'),
  ('Kabaklarda W_ beyaz, wwY_ sarı, wwyy yeşil meyve verir. WwYy genotipli F1 bitkisi wwYY genotipli sarı bir bitkiyle çaprazlanırsa döllerde fenotip oranı ne olur?', '1 beyaz : 1 sarı', ['2 beyaz : 1 sarı : 1 yeşil', '12 beyaz : 3 sarı : 1 yeşil', '1 beyaz : 1 yeşil'], 'Döllerin yarısı Ww (beyaz), yarısı ww\'dir; ww olanlar sarı ebeveynden Y aldığı için hepsi sarıdır.'),
  ('Bir hastalığın aynı ailede hem baskın hem çekinik görünümlü kalıtım örüntüleri göstermesi bazen hangi durumla açıklanır?', 'Ailede farklı genlerde ya da aynı gende farklı türde mutasyonların bulunması', ['Hastalığın tamamen çevresel olması', 'Bütün bireylerin aynı genotipte olması', 'Hastalığın yalnız Y kromozomunda bulunması'], 'Genetik heterojenlik nedeniyle aynı klinik tablo farklı mutasyonlarla ve farklı kalıtım biçimleriyle ortaya çıkabilir.'),
  ('Üç lokus bağlı olup A–B–C sırasındadır. Çift çapraz geçişle oluşan gametlerin ayrı sınıf olarak fark edilebilmesi için hangi lokusların işaretlenmiş olması gerekir?', 'Üç lokusun da', ['Yalnız en uçtaki iki lokusun', 'Yalnız ortadaki lokusun', 'Yalnız birbirine en yakın iki lokusun'], 'İki uç lokus yalnız iki kez geçişte parental düzeninde kalır; çift çaprazlanma ancak ortadaki lokusun uçlara göre yer değiştirmesiyle fark edilir. Bu yüzden üç lokusun hepsi izlenmelidir.'),
];
